window.KMAP_EXTRA.japan = {"JP-01":[{"k":"work","zh":"漫畫《黃金神威》描寫日俄戰爭退伍的士兵和愛努少女，在這裡尋找愛努人藏起來的黃金","en":"The manga Golden Kamuy follows a Russo-Japanese War veteran and an Ainu girl hunting for hidden Ainu gold here.","ja":"漫画『ゴールデンカムイ』は、日露戦争帰りの元兵士とアイヌの少女がここでアイヌの金塊を探す物語"},{"k":"symbol","zh":"官方代表花是長在海邊沙地上的玫瑰「濱梨」（ハマナス）","en":"Its official flower is the beach rose (hamanasu), which grows on seaside sands.","ja":"シンボルの花は、海辺の砂地に咲くハマナス"},{"k":"record","zh":"1902 年旭川測得 −41.0°C，是日本官方氣象觀測史上的最低氣溫","en":"Asahikawa recorded −41.0°C in 1902, the lowest temperature in Japan's official weather records.","ja":"1902年に旭川で観測された−41.0℃は、日本の気象観測史上の最低気温"},{"k":"sport","zh":"北見的冰壺隊 LS北見在 2018 平昌冬奧拿下銅牌，是日本第一面奧運冰壺獎牌","en":"Curling team Loco Solare from Kitami won bronze at PyeongChang 2018, Japan's first Olympic curling medal.","ja":"北見のロコ・ソラーレは2018年平昌五輪で銅メダル。日本カーリング初の五輪メダルだった"},{"k":"festival","zh":"「YOSAKOI索朗祭」是 1992 年一名大學生看了高知的夜來祭後，在這裡發起的","en":"The YOSAKOI Soran Festival was started here in 1992 by a university student inspired by Kōchi's Yosakoi festival.","ja":"YOSAKOIソーラン祭りは1992年、高知のよさこい祭りに感動した大学生がここで始めた"},{"k":"life","zh":"雪印的乳酸菌飲料「軟式カツゲン」幾乎只在這裡販售","en":"Snow Brand's lactic acid drink 'Soft Katsugen' is sold almost only here.","ja":"雪印メグミルクの乳酸菌飲料「ソフトカツゲン」は、ほぼここでしか売っていない"},{"k":"people","zh":"綽號「狼」、拿過 31 次優勝的橫綱千代之富士出身這裡","en":"Yokozuna Chiyonofuji, nicknamed 'the Wolf' and winner of 31 tournaments, came from here.","ja":"「ウルフ」の愛称で幕内優勝31回の横綱・千代の富士の出身地"}],
"JP-02":[{"k":"festival","zh":"八戶三社大祭的華麗山車，2016 年登錄聯合國教科文組織無形文化遺產","en":"The ornate floats of Hachinohe's Sansha Taisai festival joined UNESCO's intangible heritage list in 2016.","ja":"八戸三社大祭の山車行事は、2016年にユネスコ無形文化遺産に登録された"},{"k":"symbol","zh":"縣樹是柏科的「羅漢柏」（ヒバ）","en":"Its prefectural tree is the hiba, a Japanese cypress relative.","ja":"県の木はヒバ"},{"k":"people","zh":"以畫大眼睛、表情叛逆的小女孩聞名的藝術家奈良美智出身弘前","en":"Artist Yoshitomo Nara, famous for his big-eyed, defiant little girls, was born in Hirosaki.","ja":"目つきの鋭い少女の絵で知られる美術家・奈良美智は弘前市出身"},{"k":"work","zh":"漫畫《飛翔的魔女》描寫一位見習魔女搬到弘前的親戚家生活","en":"In the manga Flying Witch, a trainee witch moves in with relatives in Hirosaki.","ja":"漫画『ふらいんぐうぃっち』は、見習い魔女が弘前の親戚の家で暮らす物語"},{"k":"origin","zh":"名字來自港邊一座長滿青翠樹木的小丘，漁船回港時把它當成目標","en":"Its name comes from a small wooded hill by the harbor that fishing boats used as a landmark when returning.","ja":"名の由来は、漁船が帰港の目印にしていた、木々の茂る海辺の小高い丘"},{"k":"record","zh":"用不同顏色稻子在田裡作畫的「稻田藝術」，1993 年起源於這裡的田舍館村","en":"'Rice paddy art', pictures made with different-colored rice plants, began in 1993 in Inakadate village here.","ja":"色の違う稲で田に絵を描く「田んぼアート」は1993年、ここの田舎館村で始まった"},{"k":"record","zh":"八甲田山的酸湯 2013 年積雪達 566 公分，刷新氣象廳全國觀測點的紀錄","en":"Sukayu on Mt. Hakkōda logged 566 cm of snow in 2013, a record for Japan's weather stations.","ja":"八甲田山の酸ヶ湯では2013年に積雪566cmを観測し、アメダスの記録を塗り替えた"},{"k":"sport","zh":"高中足球名門「○○山田高中」2016 年後已四度拿下全國高中足球冠軍","en":"High-school soccer powerhouse '○○ Yamada' has won the national high school championship four times since 2016.","ja":"高校サッカーの強豪「○○山田」は2016年度以降、全国選手権で4度優勝"}],
"JP-03":[{"k":"symbol","zh":"縣花是桐樹的花（キリ）","en":"Its prefectural flower is the paulownia blossom.","ja":"県の花はキリ（桐）"},{"k":"people","zh":"2022 年以 20 歲之齡投出完全比賽的佐佐木朗希，出身陸前高田","en":"Rōki Sasaki, who threw a perfect game at age 20 in 2022, is from Rikuzentakata.","ja":"2022年に20歳で完全試合を達成した佐々木朗希は陸前高田市出身"},{"k":"people","zh":"畢生研究愛努語的語言學家金田一京助出身縣廳所在地","en":"Linguist Kyōsuke Kindaichi, who devoted his life to studying the Ainu language, was born in the prefectural capital.","ja":"アイヌ語研究に生涯をささげた言語学者・金田一京助は県庁所在地の出身"},{"k":"festival","zh":"「チャグチャグ馬コ」祭中，掛滿鈴鐺、盛裝打扮的馬兒一路叮噹作響地遊行","en":"At the Chagu Chagu Umakko festival, horses in colorful costumes hung with bells parade with a jingling sound.","ja":"チャグチャグ馬コでは、鈴をたくさん付けて着飾った馬が音を鳴らして行進する"},{"k":"record","zh":"縣廳所在地的「さんさ舞」以 3 千多人同時打太鼓，獲金氏認證為世界最大和太鼓合奏","en":"The Sansa Odori festival in the capital holds a Guinness record for the largest Japanese drum ensemble: over 3,000 drummers.","ja":"県庁所在地のさんさ踊りは、3千人超の和太鼓同時演奏でギネス世界記録に認定"},{"k":"origin","zh":"傳說作惡的鬼被神懲罰，在大石上按下手印發誓不再作亂，成了名字由來","en":"Legend says a demon, punished by the gods, pressed its handprint into a big rock as a vow to behave, giving the name.","ja":"悪さをした鬼が神に懲らしめられ、大岩に手形を押して誓ったという伝説が名の由来"},{"k":"sport","zh":"「橄欖球之城」釜石：新日鐵釜石隊在 1980 年前後達成日本選手權 7 連霸","en":"Kamaishi is a rugby town: Nippon Steel Kamaishi won seven straight national championships around 1980.","ja":"ラグビーの街・釜石。新日鉄釜石は1980年前後に日本選手権7連覇を果たした"},{"k":"work","zh":"宮澤賢治筆下的理想鄉「伊哈托布（イーハトーブ）」以這裡為原型","en":"Kenji Miyazawa's dreamland 'Ihatov' was modeled on this place.","ja":"宮沢賢治が描いた理想郷「イーハトーブ」のモデル"}],
"JP-04":[{"k":"symbol","zh":"縣鳥是雁；伊豆沼清晨雁群齊飛的振翅聲，入選「日本音風景百選」","en":"Its prefectural bird is the goose; the sound of geese taking off at dawn over Izunuma is one of Japan's 100 Soundscapes.","ja":"県の鳥はガン。伊豆沼でマガンが一斉に飛び立つ音は「日本の音風景100選」"},{"k":"people","zh":"創作《假面騎士》《人造人009》的石之森章太郎出身登米","en":"Shōtarō Ishinomori, creator of Kamen Rider and Cyborg 009, was born in Tome.","ja":"『仮面ライダー』『サイボーグ009』の石ノ森章太郎は登米市出身"},{"k":"work","zh":"《JOJO的奇妙冒險》第四部的「杜王町」，以作者故鄉、這裡的縣廳所在地為原型","en":"Morioh, the town in JoJo's Bizarre Adventure Part 4, is modeled on the author's hometown, the prefectural capital.","ja":"『ジョジョ』第4部の杜王町は、作者の故郷であるここの県庁所在地がモデル"},{"k":"work","zh":"伊坂幸太郎的小說《Golden Slumber 宅配男與披頭四搖籃曲》以縣廳所在地為舞台","en":"Kōtarō Isaka's novel Golden Slumber is set in the prefectural capital.","ja":"伊坂幸太郎の小説『ゴールデンスランバー』の舞台は県庁所在地"},{"k":"festival","zh":"どんと祭的「裸參拜」，男人纏著白布、口咬白紙以免氣息碰到神明，走向神社","en":"At Donto-sai, men in white cloth make 'naked pilgrimages' to shrines, biting paper so their breath won't touch the gods.","ja":"どんと祭の裸参りでは、さらし姿の男たちが神に息がかからないよう紙をくわえて歩く"},{"k":"life","zh":"縣廳所在地的中華料理店「龍亭」1937 年推出夏季涼麵，被視為冷やし中華的發祥之一","en":"Ryūtei, a Chinese restaurant in the capital, launched a summer cold noodle in 1937, seen as one origin of hiyashi chūka.","ja":"県庁所在地の「龍亭」が1937年に出した夏の麺は、冷やし中華の元祖のひとつとされる"},{"k":"sport","zh":"達比修有高中就讀這裡的東北高中，曾在甲子園投出無安打比賽","en":"Yu Darvish attended Tōhoku High School here and threw a no-hitter at Kōshien.","ja":"ダルビッシュ有は東北高校出身で、甲子園でノーヒットノーランを達成した"},{"k":"people","zh":"搞笑組合「三明治人」兩人都出身這裡，2007 年拿下 M-1 大賽冠軍","en":"Comedy duo Sandwichman, both from here, won the M-1 Grand Prix in 2007.","ja":"お笑いコンビ・サンドウィッチマンは2人ともここの出身で、2007年のM-1王者"}],
"JP-05":[{"k":"symbol","zh":"縣花是早春從雪地冒出來的蜂斗菜花苞「ふきのとう」","en":"Its prefectural flower is fukinotō, the butterbur bud that pokes through the snow in early spring.","ja":"県の花は、雪解けとともに顔を出すふきのとう"},{"k":"symbol","zh":"縣魚是冬天打雷時成群靠岸的「鰰」（ハタハタ）","en":"Its prefectural fish is the sandfish (hatahata), which swarms the coast in winter when thunder rolls.","ja":"県の魚は、冬の雷の頃に押し寄せるハタハタ（鰰）"},{"k":"people","zh":"日本職棒史上唯一三度拿下打擊三冠王的落合博滿出身這裡","en":"Hiromitsu Ochiai, the only player in Japanese pro baseball to win the Triple Crown three times, is from here.","ja":"プロ野球史上唯一、3度の三冠王に輝いた落合博満の出身地"},{"k":"work","zh":"《灌籃高手》最強對手「山王工業」，原型被認為是這裡的能代工業高中","en":"Sannoh Kogyo, the toughest rival in Slam Dunk, is said to be modeled on Noshiro Technical High School here.","ja":"『SLAM DUNK』の最強校・山王工業のモデルとされるのは、ここの能代工業高校"},{"k":"sport","zh":"2018 年夏季甲子園，公立農業高中「金足農」一路打進決賽，掀起「金農旋風」","en":"In 2018, public agricultural school Kanaashi Nōgyō stormed to the summer Kōshien final, sparking a national craze.","ja":"2018年夏の甲子園で公立の金足農業が準優勝し、「金農旋風」を巻き起こした"},{"k":"festival","zh":"橫手的雪屋祭「かまくら」，是武士町的左義長和商人町的水神祭合而為一","en":"Yokote's kamakura snow-hut festival grew from merging a samurai district's fire rite with a merchants' water-god festival.","ja":"横手のかまくらは、武家町の左義長と町人町の水神祭りが合わさって生まれた"},{"k":"life","zh":"夏天路邊的「Babahera 冰淇淋」：大媽用鏟子把粉紅和黃色冰淇淋堆成玫瑰花","en":"In summer, roadside 'Babahera' ladies scoop pink and yellow ice cream into rose shapes with a spatula.","ja":"夏の道端で、おばちゃんがヘラでピンクと黄色のアイスをバラの形に盛る「ババヘラアイス」"},{"k":"record","zh":"國家指定的「重要無形民俗文化財」件數全國最多","en":"It has more nationally designated Important Intangible Folk Cultural Properties than any other prefecture.","ja":"国の重要無形民俗文化財の指定件数が全国最多"}],
"JP-06":[{"k":"symbol","zh":"縣花是紅花，江戶時代做成胭脂與染料，讓當地商人致富","en":"Its prefectural flower is the safflower, which in the Edo period made local merchants rich as a source of rouge and dye.","ja":"県の花は紅花。江戸時代には口紅や染料の原料として商人に富をもたらした"},{"k":"festival","zh":"夏日祭典中，大批舞者戴著綴有紅花的斗笠，邊喊「ヤッショ、マカショ」邊跳舞","en":"At a summer festival, crowds of dancers in safflower-decorated straw hats dance chanting 'Yassho, makasho!'","ja":"花笠をかぶった大勢の踊り手が「ヤッショ、マカショ」と掛け声をあげて踊る夏祭り"},{"k":"people","zh":"近代短歌巨匠、同時也是精神科醫師的齋藤茂吉出身上山","en":"Mokichi Saitō, a master of modern tanka poetry who was also a psychiatrist, was born in Kaminoyama.","ja":"近代短歌の巨匠で精神科医でもあった斎藤茂吉は上山市の出身"},{"k":"origin","zh":"名字源自平安時代辭書《和名類聚抄》記載的「山方鄉」","en":"Its name is said to derive from an ancient district written 山方 ('mountain side'), recorded in a Heian-era dictionary.","ja":"名の由来は『和名類聚抄』に載る「山方郷」とされる"},{"k":"life","zh":"縣廳所在地每戶外食吃拉麵的支出，常年是全國第一","en":"Households in the capital spend more on eating out at ramen shops than anywhere else in Japan, year after year.","ja":"県庁所在地は1世帯あたりの外食ラーメン支出が、長年全国1位"},{"k":"work","zh":"奧斯卡最佳外語片《送行者：禮儀師的樂章》主要在酒田拍攝","en":"Departures, the Oscar-winning film about an encoffiner, was mainly shot in Sakata.","ja":"アカデミー賞外国語映画賞の『おくりびと』の主なロケ地は酒田市"},{"k":"work","zh":"NHK 晨間劇《阿信》開頭，主角在最上川沿岸的貧農家庭度過童年","en":"NHK drama Oshin opens with its heroine's childhood in a poor farming family along the Mogami River here.","ja":"NHK朝ドラ『おしん』は、主人公が最上川流域の貧しい農家で過ごす少女時代から始まる"}],
"JP-07":[{"k":"symbol","zh":"縣花是高山植物「根本石楠花」（ネモトシャクナゲ）","en":"Its prefectural flower is the Nemoto rhododendron, an alpine plant.","ja":"県の花は高山植物のネモトシャクナゲ"},{"k":"people","zh":"寫出阪神虎隊歌《六甲颪》的作曲家古關裕而出身這裡，晨間劇《Yell》以他為原型","en":"Composer Yūji Koseki, who wrote the Hanshin Tigers' anthem 'Rokkō Oroshi', was born here; NHK's drama Yell is based on him.","ja":"阪神の「六甲おろし」を作曲した古関裕而の出身地。朝ドラ『エール』のモデル"},{"k":"festival","zh":"「相馬野馬追」：數百名身穿盔甲的騎馬武士，爭奪射上天空的神旗","en":"At Sōma Nomaoi, hundreds of armored samurai on horseback race to catch sacred flags shot into the sky.","ja":"相馬野馬追では、甲冑姿の騎馬武者数百騎が打ち上げられた御神旗を奪い合う"},{"k":"work","zh":"大河劇《八重之櫻》的主角新島八重，是戊辰戰爭時拿槍守城的會津女子","en":"Niijima Yae, heroine of the NHK drama Yae's Sakura, was an Aizu woman who fought with a rifle in the Boshin War.","ja":"大河ドラマ『八重の桜』の主人公・新島八重は、戊辰戦争で銃を手に戦った会津の女性"},{"k":"origin","zh":"據《古事記》，兩位將軍父子在此相會，因此原寫作「相津」，後來成了「會津」","en":"Per the Kojiki, a general and his son met here, so the area was named 相津 ('meeting port'), later written Aizu.","ja":"『古事記』によれば、将軍の父子がここで出会ったことから「相津」と呼ばれ、のちの会津になった"},{"k":"record","zh":"全國新酒鑑評會的金賞數量，曾史上首度連續 9 屆全國第一","en":"It won the most gold medals at Japan's national new sake competition nine times in a row, a first in history.","ja":"全国新酒鑑評会の金賞受賞数で、史上初の9回連続日本一"},{"k":"life","zh":"會津藩武士子弟守則「什之掟」最後一句是：「不行的事就是不行」","en":"The Aizu domain's code for samurai children ends with: 'What must not be done, must not be done.'","ja":"会津藩の子弟の掟「什の掟」は「ならぬことはならぬものです」で結ばれる"},{"k":"sport","zh":"日本國家足球隊的訓練中心「J-Village」在這裡，核災後曾當作應變據點","en":"J-Village, Japan's national soccer training center, is here; after the 2011 nuclear accident it served as a response base.","ja":"サッカー日本代表の練習拠点「Jヴィレッジ」がある。原発事故後は対応拠点になった"}],
"JP-08":[{"k":"symbol","zh":"縣花是玫瑰（バラ）","en":"Its prefectural flower is the rose.","ja":"県の花はバラ"},{"k":"origin","zh":"據《常陸國風土記》，古代將軍用帶刺的荊棘築城抵禦盜賊，成了名字由來","en":"Per an ancient gazetteer, a general built a fort of thorny brambles to fend off bandits, which gave the place its name.","ja":"『常陸国風土記』によれば、黒坂命が賊を防ぐため茨で城を築いたのが名の由来"},{"k":"life","zh":"民間調查「都道府縣魅力度排行」中，曾連續 7 年排名最後一名","en":"It came dead last in a private 'prefecture attractiveness ranking' seven years in a row.","ja":"民間の「都道府県魅力度ランキング」で7年連続最下位だったことがある"},{"k":"festival","zh":"「日立風流物」是高約 15 公尺的巨大山車，上面的機關人偶會演出戲碼","en":"Hitachi Furyūmono is a giant 15 m float on which mechanical puppets act out plays.","ja":"日立風流物は高さ約15mの巨大な山車で、からくり人形が芝居を演じる"},{"k":"work","zh":"動畫《少女與戰車》以大洗町為舞台，掀起聖地巡禮熱潮","en":"The anime Girls und Panzer is set in Ōarai, sparking a wave of fan pilgrimages.","ja":"アニメ『ガールズ&パンツァー』の舞台は大洗町。聖地巡礼ブームを呼んだ"},{"k":"people","zh":"近代日本畫巨匠橫山大觀出身縣廳所在地","en":"Yokoyama Taikan, a giant of modern Japanese-style painting, was born in the prefectural capital.","ja":"近代日本画の巨匠・横山大観は県庁所在地の出身"},{"k":"sport","zh":"2017 年成為睽違 19 年的日本出身橫綱稀勢之里，在這裡的牛久長大","en":"Kisenosato, who in 2017 became the first Japan-born yokozuna in 19 years, grew up in Ushiku here.","ja":"2017年に19年ぶりの日本出身横綱となった稀勢の里は牛久市育ち"},{"k":"record","zh":"給人京都蔬菜印象的水菜，收穫量全國第一其實在這裡","en":"Mizuna, a green associated with Kyoto, is actually grown most here.","ja":"京野菜のイメージが強い水菜の収穫量は、実はここが全国1位"}],
"JP-09":[{"k":"symbol","zh":"縣花是杜鵑的一種「八汐躑躅」（やしおつつじ）","en":"Its prefectural flower is the yashio azalea.","ja":"県の花はやしおつつじ"},{"k":"festival","zh":"每年春秋，上千人扮成武士，重現德川家康遷葬的「千人武者行列」","en":"Each spring and autumn, a 'thousand-warrior procession' re-enacts the transfer of Tokugawa Ieyasu's remains.","ja":"春と秋、千人の武者姿で家康の改葬を再現する「百物揃千人武者行列」"},{"k":"people","zh":"前 WBC 世界拳王、以「OK 牧場」口頭禪聞名的 Guts 石松出身鹿沼","en":"Guts Ishimatsu, former WBC world boxing champion known for the catchphrase 'OK Bokujō', is from Kanuma.","ja":"元WBC世界王者で「OK牧場」でおなじみのガッツ石松は鹿沼市出身"},{"k":"origin","zh":"名字一說來自神社屋頂上 10 支交叉的「千木」，稱為「十千木」","en":"One theory says the name comes from the ten crossed roof beams (chigi) on a local shrine.","ja":"神明宮の社殿にあった10本の千木「十千木（とおちぎ）」が名の由来という説がある"},{"k":"sport","zh":"MotoGP 機車世界錦標賽的日本站，在這裡的茂木賽道舉行","en":"The MotoGP Japanese Grand Prix is held at the Motegi circuit here.","ja":"MotoGP日本グランプリの会場は、ここの茂木町にあるサーキット"},{"k":"life","zh":"以這裡為中心的鄉土菜「しもつかれ」，把鮭魚頭、蘿蔔泥、酒粕煮成一鍋，外觀嚇人","en":"Shimotsukare, a local dish of salmon heads, grated radish and sake lees stewed together, is notoriously scary-looking.","ja":"郷土料理しもつかれは鮭の頭・大根おろし・酒粕を煮込んだもので、見た目が強烈"},{"k":"record","zh":"伊呂波坂山路共有 48 個彎道，每個彎都標上一個「いろは」假名","en":"The Irohazaka road has 48 hairpin turns, each marked with one kana of the old 'iroha' poem.","ja":"いろは坂には48のカーブがあり、それぞれに「い」「ろ」「は」…の文字が付く"},{"k":"record","zh":"縣廳所在地夏季打雷的日數全國最多，被稱為「雷都」","en":"The capital has the most thunderstorm days in Japan from spring to autumn and is called the 'Thunder City'.","ja":"県庁所在地は4〜9月の雷発生日数が全国最多で、「雷都」と呼ばれる"}],
"JP-10":[{"k":"symbol","zh":"縣吉祥物是一匹小馬，2014 年拿下全國吉祥物大賽冠軍","en":"Its mascot, a little pony, won Japan's Yuru-chara Grand Prix in 2014.","ja":"県のマスコットは子馬のキャラクターで、2014年のゆるキャラグランプリで優勝"},{"k":"work","zh":"《頭文字D》主角拓海送豆腐的「秋名山」，原型是這裡的榛名山","en":"Mt. Akina, where Initial D's Takumi delivers tofu, is modeled on Mt. Haruna here.","ja":"『頭文字D』で拓海が豆腐を配達する「秋名」のモデルは榛名山"},{"k":"people","zh":"遊戲《MOTHER》的創作者、知名文案人糸井重里出身縣廳所在地","en":"Shigesato Itoi, creator of the game Mother and a famed copywriter, was born in the prefectural capital.","ja":"ゲーム『MOTHER』の生みの親でコピーライターの糸井重里は県庁所在地の出身"},{"k":"people","zh":"被譽為「日本近代詩之父」的萩原朔太郎出身縣廳所在地","en":"Sakutarō Hagiwara, called the father of modern Japanese poetry, was born in the prefectural capital.","ja":"「日本近代詩の父」と呼ばれる萩原朔太郎は県庁所在地の出身"},{"k":"origin","zh":"名字源自古代的「車郡」，後來改寫成兩個吉祥的漢字","en":"The name derives from the ancient 'Kuruma' (cart) district, later rewritten with auspicious characters.","ja":"古代の「車（くるま）」の郡が由来で、のちに縁起のよい2文字に改められた"},{"k":"record","zh":"草津溫泉的自然湧出量是日本第一","en":"Kusatsu Onsen has the largest natural flow of hot spring water in Japan.","ja":"草津温泉は自然湧出量が日本一"},{"k":"life","zh":"大泉町約五分之一居民是外國人，巴西人尤其多，被稱為「小巴西」","en":"About one in five residents of Ōizumi town is foreign, many of them Brazilian; it's nicknamed 'Little Brazil'.","ja":"大泉町は住民の約2割が外国人でブラジル人が多く、「リトルブラジル」と呼ばれる"},{"k":"life","zh":"持有駕照的人口比例全國最高","en":"It has the highest share of driver's-license holders in Japan.","ja":"運転免許保有率が全国1位"}],
"JP-11":[{"k":"symbol","zh":"縣吉祥物「コバトン」的原型，是縣鳥灰斑鳩（シラコバト）","en":"Its mascot Kobaton is based on the prefectural bird, the Eurasian collared dove.","ja":"県のマスコット「コバトン」は、県民の鳥シラコバトがモデル"},{"k":"work","zh":"動畫《幸運☆星》讓鷲宮神社成了動漫聖地巡禮的先驅","en":"The anime Lucky Star made Washinomiya Shrine one of the first anime pilgrimage sites.","ja":"アニメ『らき☆すた』で鷲宮神社は聖地巡礼の先駆けになった"},{"k":"work","zh":"動畫《我們仍未知道那天所看見的花名。》以秩父為舞台","en":"The anime Anohana: The Flower We Saw That Day is set in Chichibu.","ja":"アニメ『あの日見た花の名前を僕達はまだ知らない。』の舞台は秩父市"},{"k":"people","zh":"第一位擔任國際太空站站長的日本太空人若田光一出身這裡","en":"Kōichi Wakata, the first Japanese commander of the International Space Station, was born here.","ja":"日本人初の国際宇宙ステーション船長・若田光一の出身地"},{"k":"festival","zh":"鴻巢的「驚奇女兒節」把人偶擺上 31 層、高 7 公尺的金字塔台，號稱日本最高","en":"Kōnosu's 'Surprise Doll Festival' stacks hina dolls on a 31-tier, 7 m pyramid, said to be Japan's tallest.","ja":"鴻巣の「びっくりひな祭り」には31段・高さ7mの日本一高いピラミッドひな壇が登場"},{"k":"sport","zh":"職棒西武獅的主場在這裡的所澤","en":"The Seibu Lions baseball team plays its home games in Tokorozawa here.","ja":"プロ野球・西武ライオンズの本拠地は所沢市"},{"k":"record","zh":"大量居民到外縣通勤通學，「晝夜間人口比率」全國最低","en":"So many residents commute out of the prefecture that its daytime-to-nighttime population ratio is the lowest in Japan.","ja":"県外への通勤・通学者が多く、昼夜間人口比率は全国最低"}],
"JP-12":[{"k":"symbol","zh":"縣吉祥物是一隻紅色的狗，側面輪廓剛好就是縣的形狀","en":"Its mascot is a red dog whose side profile is exactly the shape of the prefecture.","ja":"県のマスコットは赤い犬で、横から見た姿が県の形そのもの"},{"k":"life","zh":"船橋市的非官方吉祥物「船梨精」是一顆會尖叫、亂跳的梨子","en":"Funabashi's unofficial mascot Funassyi is a pear fairy that shrieks and jumps around wildly.","ja":"船橋市の非公認キャラ「ふなっしー」は、奇声を上げて跳ね回る梨の妖精"},{"k":"record","zh":"日本梨的產量全國第一","en":"It grows more Japanese pears than any other prefecture.","ja":"日本梨の収穫量が全国1位"},{"k":"work","zh":"自行車漫畫《飆速宅男》的主角就讀這裡的總北高中","en":"In the cycling manga Yowamushi Pedal, the hero attends Sōhoku High School here.","ja":"自転車漫画『弱虫ペダル』の主人公は、ここの総北高校に通う"},{"k":"sport","zh":"職棒羅德海洋隊的主場在這裡，球場以強勁海風出名","en":"The Lotte Marines baseball team plays here, at a stadium famous for strong sea winds.","ja":"プロ野球ロッテの本拠地があり、球場は海風が強いことで有名"},{"k":"festival","zh":"佐原大祭的山車上有巨大人偶，2016 年登錄聯合國教科文組織無形文化遺產","en":"Sawara's grand festival features floats topped with giant figures; it joined UNESCO's intangible heritage list in 2016.","ja":"佐原の大祭は巨大な人形を載せた山車が特徴で、2016年にユネスコ無形文化遺産に"},{"k":"origin","zh":"名字的意思是「許多葉子茂盛生長」，寄託土地與子孫繁榮的願望","en":"The name means 'a thousand leaves', expressing wishes for a thriving land and descendants.","ja":"名は「多くの葉が茂る」の意で、土地と子孫の繁栄を願ったものとされる"},{"k":"people","zh":"日蓮宗的開山祖師日蓮出身這裡的安房小湊","en":"Nichiren, founder of Nichiren Buddhism, was born in Awa-Kominato here.","ja":"日蓮宗の開祖・日蓮は安房小湊の出身"}],
"JP-13":[{"k":"symbol","zh":"代表鳥是紅嘴鷗，就是《伊勢物語》裡被稱為「都鳥」的那種鳥","en":"Its official bird is the black-headed gull, the 'miyakodori' of the classic Tales of Ise.","ja":"シンボルの鳥はユリカモメ。『伊勢物語』に詠まれた「都鳥」とされる"},{"k":"work","zh":"吉卜力動畫《心之谷》以多摩地區的聖蹟櫻丘一帶為舞台","en":"Studio Ghibli's Whisper of the Heart is set around Seiseki-Sakuragaoka in the Tama area.","ja":"ジブリ『耳をすませば』の舞台は多摩市の聖蹟桜ヶ丘周辺"},{"k":"people","zh":"曾印在千圓鈔票上的文豪夏目漱石出身這裡的牛込","en":"Natsume Sōseki, the novelist once on the 1,000-yen note, was born in Ushigome here.","ja":"千円札の肖像だった夏目漱石は牛込の出身"},{"k":"festival","zh":"神田祭和山王祭是獲准讓遊行隊伍進入江戶城的「天下祭」","en":"The Kanda and Sannō festivals were 'festivals of the realm' whose processions were allowed into Edo Castle.","ja":"神田祭と山王祭は、行列が江戸城に入ることを許された「天下祭」"},{"k":"origin","zh":"銀座這個地名，來自江戶時代在此鑄造銀幣的「銀座」","en":"The Ginza district is named after the Edo-period silver mint that stood there.","ja":"銀座の地名は、江戸時代に銀貨を鋳造した「銀座」があったことに由来"},{"k":"record","zh":"2007 年米其林首次在這裡評鑑，星星總數就是全球城市之冠","en":"In its first Michelin guide in 2007, its restaurants earned the most stars of any city.","ja":"2007年のミシュラン初版で、星の総数が世界の都市で最多になった"},{"k":"sport","zh":"職棒巨人隊與養樂多燕子隊兩支球隊的主場都在這裡","en":"Both the Yomiuri Giants and the Yakult Swallows play their home games here.","ja":"プロ野球の巨人とヤクルト、2球団の本拠地がある"},{"k":"life","zh":"伊豆群島名產「くさや」魚乾，用代代相傳的醃汁浸漬，臭味驚人","en":"The Izu Islands' kusaya, fish cured in brine passed down for generations, is famous for its overpowering smell.","ja":"伊豆諸島名物のくさやは、代々受け継ぐ漬け汁に漬けた干物で、強烈な臭いがする"}],
"JP-14":[{"k":"symbol","zh":"縣花是花朵碩大、香氣濃郁的山百合","en":"Its prefectural flower is the golden-rayed lily, with large, fragrant blooms.","ja":"県の花は、大きな花と強い香りのヤマユリ"},{"k":"work","zh":"《新世紀福音戰士》裡的「第3新東京市」，設定在這裡的箱根","en":"Tokyo-3, the city in Neon Genesis Evangelion, is set in Hakone here.","ja":"『エヴァンゲリオン』の第3新東京市は、箱根にある設定"},{"k":"work","zh":"《灌籃高手》片頭出現的平交道，就在江之電鎌倉高校前站旁","en":"The railroad crossing in Slam Dunk's opening is next to Kamakura-Kōkōmae Station on the Enoden line.","ja":"『SLAM DUNK』のOPに出る踏切は、江ノ電・鎌倉高校前駅のそば"},{"k":"sport","zh":"職棒 DeNA 海灣之星和 J 聯盟川崎前鋒都以這裡為主場","en":"Pro baseball's DeNA BayStars and soccer's Kawasaki Frontale are both based here.","ja":"プロ野球DeNAとJリーグ川崎フロンターレの本拠地"},{"k":"festival","zh":"鶴岡八幡宮的「流鏑馬」：身穿武士裝束的射手在疾馳的馬上射靶","en":"At Tsurugaoka Hachimangū's yabusame, archers in samurai dress shoot targets from galloping horses.","ja":"鶴岡八幡宮の流鏑馬では、武士装束の射手が疾走する馬上から的を射る"},{"k":"people","zh":"南方之星主唱桑田佳祐出身茅崎，常在歌裡唱湘南的海","en":"Southern All Stars frontman Keisuke Kuwata is from Chigasaki and often sings about the Shōnan coast.","ja":"サザンオールスターズの桑田佳祐は茅ヶ崎市出身で、湘南の海をよく歌う"},{"k":"record","zh":"全國唯一擁有三座政令指定都市的縣","en":"It is the only prefecture with three government-designated major cities.","ja":"政令指定都市が3つある唯一の県"},{"k":"record","zh":"1869 年，日本第一支冰淇淋「あいすくりん」在這裡的馬車道開賣","en":"Japan's first ice cream, 'aisukurin', went on sale on Bashamichi street here in 1869.","ja":"1869年、ここの馬車道で日本初のアイスクリーム「あいすくりん」が売られた"}],
"JP-15":[{"k":"symbol","zh":"縣樹是在大雪中也能開花的「雪椿」","en":"Its prefectural tree is the snow camellia, which blooms despite heavy snow.","ja":"県の木は、雪に耐えて咲くユキツバキ"},{"k":"people","zh":"策劃偷襲珍珠港的聯合艦隊司令長官山本五十六出身長岡","en":"Admiral Isoroku Yamamoto, who planned the Pearl Harbor attack, was born in Nagaoka.","ja":"真珠湾攻撃を立案した連合艦隊司令長官・山本五十六は長岡出身"},{"k":"work","zh":"川端康成《雪國》開頭「穿過縣界長長的隧道」，舞台就在湯澤","en":"Kawabata's Snow Country, which opens with a train leaving a long tunnel into snow, is set in Yuzawa here.","ja":"川端康成『雪国』の「国境の長いトンネルを抜けると」の舞台は湯沢町"},{"k":"festival","zh":"長岡煙火大會的「鳳凰」煙火，是為祈求 2004 年地震後的復興而開始施放","en":"Nagaoka's fireworks feature 'Phoenix', launched to pray for recovery after the 2004 earthquake.","ja":"長岡まつり大花火大会の「フェニックス」は、中越地震からの復興を願って始まった"},{"k":"festival","zh":"名字裡有「富士」的富士搖滾音樂祭，1999 年起其實都在這裡的苗場舉辦","en":"Despite its name, the Fuji Rock Festival has been held at Naeba here since 1999.","ja":"名前に「富士」とつくフジロックは、1999年からここの苗場で開かれている"},{"k":"record","zh":"1888 年人口約 166 萬，是當時全國人口最多的縣，東京只排第 4","en":"In 1888, with about 1.66 million people, it was Japan's most populous prefecture; Tokyo ranked only fourth.","ja":"1888年には人口約166万人で全国最多。東京は4位だった"},{"k":"life","zh":"在地速食「義大利麵（イタリアン）」其實是淋上番茄肉醬的炒麵","en":"The local fast food called 'Italian' is actually yakisoba topped with tomato meat sauce.","ja":"ご当地ファストフード「イタリアン」の正体は、ミートソースをかけた焼きそば"}],
"JP-16":[{"k":"symbol","zh":"縣樹是立山山區的杉樹「立山杉」","en":"Its prefectural tree is the Tateyama cedar.","ja":"県の木はタテヤマスギ"},{"k":"work","zh":"細田守動畫《狼的孩子雨和雪》的鄉間場景，以他的故鄉上市町為原型","en":"The countryside in Mamoru Hosoda's Wolf Children is modeled on his hometown, Kamiichi.","ja":"細田守監督『おおかみこどもの雨と雪』の田舎は、監督の故郷・上市町がモデル"},{"k":"work","zh":"電影《劍岳：點之記》描寫明治時代的測量隊挑戰攀登劍岳","en":"The film Tsurugidake chronicles a Meiji-era survey team's climb of Mt. Tsurugi here.","ja":"映画『劔岳 点の記』は、明治の測量隊が劔岳に挑む姿を描く"},{"k":"festival","zh":"越中八尾的「風之盆」：人們在胡弓聲中，三天三夜靜靜跳舞穿過街巷","en":"During Owara Kaze-no-Bon in Yatsuo, dancers weave through the streets to the kokyū fiddle for three days and nights.","ja":"越中八尾の「おわら風の盆」では、胡弓の音色にのせて三日三晩踊り歩く"},{"k":"people","zh":"《忍者哈特利》的作者藤子不二雄Ⓐ出身冰見","en":"Fujiko Fujio Ⓐ, creator of Ninja Hattori-kun, was born in Himi.","ja":"『忍者ハットリくん』の藤子不二雄Ⓐは氷見市出身"},{"k":"people","zh":"讀賣新聞社主、被稱為「職棒之父」的正力松太郎出身這裡","en":"Matsutarō Shōriki, the Yomiuri newspaper owner called the father of Japanese pro baseball, was born here.","ja":"読売新聞社主で「プロ野球の父」と呼ばれる正力松太郎の出身地"},{"k":"record","zh":"稱名瀑布落差約 350 公尺，是日本落差最大的瀑布","en":"Shōmyō Falls drops about 350 m, the tallest waterfall in Japan.","ja":"称名滝は落差約350mで日本一"},{"k":"life","zh":"春天在魚津海岸可以看到海市蜃樓，對岸的景物彷彿浮在海上","en":"In spring, mirages can appear off the Uozu coast, with distant shores seeming to float above the sea.","ja":"春の魚津の海岸では蜃気楼が現れ、対岸の景色が海上に浮かんで見える"}],
"JP-17":[{"k":"symbol","zh":"縣花是開在白山高處的黑百合","en":"Its prefectural flower is the black lily, an alpine bloom of Mt. Haku.","ja":"県の花は白山に咲く高山植物クロユリ"},{"k":"symbol","zh":"縣鳥是猛禽「金鵰」（イヌワシ）","en":"Its prefectural bird is the golden eagle.","ja":"県の鳥はイヌワシ"},{"k":"festival","zh":"能登的「切子祭」扛著點燈的巨大方形燈籠遊行，有的高超過 10 公尺","en":"In Noto's Kiriko festivals, people carry giant illuminated lantern towers, some over 10 m tall.","ja":"能登のキリコ祭りでは、高さ10mを超すものもある巨大な灯籠キリコを担ぐ"},{"k":"people","zh":"以怪奇幻想小說《高野聖》聞名的泉鏡花出身縣廳所在地","en":"Izumi Kyōka, author of the eerie fantasy The Holy Man of Mount Kōya, was born in the prefectural capital.","ja":"幻想小説『高野聖』の泉鏡花は県庁所在地の出身"},{"k":"work","zh":"湯涌溫泉的「燈籠祭」，是 2011 年把動畫《花開伊呂波》裡虛構的祭典搬到現實","en":"Yuwaku Onsen's Bonbori Festival brought a fictional festival from the anime Hanasaku Iroha to life in 2011.","ja":"湯涌温泉の「ぼんぼり祭り」は、アニメ『花咲くいろは』の架空の祭りを2011年に現実にしたもの"},{"k":"origin","zh":"縣廳所在地的名字，傳說來自農夫在泉水邊洗山芋時洗出了砂金","en":"Legend says the capital's name comes from a spring where a farmer washing yams found gold dust.","ja":"県庁所在地の名は、芋掘り藤五郎が芋を洗った泉から砂金が出た伝説に由来"},{"k":"sport","zh":"2025 年以入門 13 場所的史上最快速度晉升橫綱的大之里，出身津幡町","en":"Ōnosato, who became yokozuna in 2025 just 13 tournaments after his debut, a record, is from Tsubata.","ja":"初土俵から史上最速の13場所で2025年に横綱昇進した大の里は津幡町出身"},{"k":"life","zh":"縣廳所在地每戶買和菓子的支出，長年是全國第一","en":"Households in the capital spend more on Japanese sweets than anywhere else in Japan.","ja":"県庁所在地は1世帯あたりの和菓子支出が全国1位の常連"}],
"JP-18":[{"k":"symbol","zh":"縣花是寒冬時在越前海岸盛開的水仙","en":"Its prefectural flower is the narcissus, which blooms along the Echizen coast in winter.","ja":"県の花は、冬の越前海岸に咲くスイセン"},{"k":"symbol","zh":"縣鳥是冬天飛來過冬的斑點鶇（ツグミ）","en":"Its prefectural bird is the dusky thrush, a winter visitor.","ja":"県の鳥は冬鳥のツグミ"},{"k":"life","zh":"民間「都道府縣幸福度排行」中，連續多次拿下總合第一","en":"It has repeatedly ranked No. 1 overall in a private happiness ranking of Japan's prefectures.","ja":"民間の「都道府県幸福度ランキング」で、総合1位を何度も連続で獲得"},{"k":"people","zh":"演歌歌手五木宏出身美濱町","en":"Enka singer Hiroshi Itsuki was born in Mihama.","ja":"演歌歌手・五木ひろしは美浜町出身"},{"k":"work","zh":"漫畫《花牌情緣》中，主角的競技歌牌勁敵綿谷新來自這裡","en":"In the manga Chihayafuru, Arata Wataya, the heroine's karuta rival, is from here.","ja":"漫画『ちはやふる』で、千早のライバル・綿谷新はここの出身という設定"},{"k":"festival","zh":"勝山的「左義長祭」在街頭高台上敲「浮太鼓」，最後把松飾集中燒掉","en":"At Katsuyama's Sagichō festival, drummers play 'floating drums' on street towers, then the pine decorations are burned.","ja":"勝山左義長まつりでは櫓の上で浮き太鼓を打ち、最後に松飾りを集めて燃やす"},{"k":"origin","zh":"原本叫「北之庄」，江戶時代嫌「北」有敗北之意而改名","en":"Originally called Kitanoshō; it was renamed in the Edo period because 'kita' (north) evokes defeat.","ja":"もとは「北ノ庄」。「北」が敗北に通じるとして江戸時代に改名された"},{"k":"life","zh":"水羊羹在這裡是冬天窩在暖桌裡吃的點心","en":"Here, mizu-yōkan (soft red bean jelly) is a winter treat eaten under the kotatsu.","ja":"ここでは水ようかんは冬にこたつで食べるもの"}],
"JP-19":[{"k":"symbol","zh":"縣花是富士山麓開的小花櫻花「富士櫻」","en":"Its prefectural flower is the Fuji cherry, a small-flowered cherry of Mt. Fuji's foothills.","ja":"県の花は富士山麓に咲くフジザクラ"},{"k":"festival","zh":"「信玄公祭」上千人穿盔甲重現武田軍出陣，獲金氏認證為世界最大武者行列","en":"At the Shingen-kō Festival, over a thousand armored people re-enact Takeda's army: a Guinness-record samurai parade.","ja":"信玄公祭りの甲州軍団出陣は「世界最大の武者行列」としてギネス認定"},{"k":"work","zh":"露營動畫《搖曳露營△》的主要舞台在本栖湖和身延町一帶","en":"The camping anime Laid-Back Camp is mainly set around Lake Motosu and Minobu here.","ja":"キャンプアニメ『ゆるキャン△』の主な舞台は本栖湖や身延町の周辺"},{"k":"people","zh":"阪急電鐵、寶塚歌劇團與東寶的創辦人小林一三出身韮崎","en":"Ichizō Kobayashi, founder of Hankyu Railway, the Takarazuka Revue and Toho, was born in Nirasaki.","ja":"阪急電鉄・宝塚歌劇団・東宝を築いた小林一三は韮崎市出身"},{"k":"people","zh":"直木獎作家、日本大學理事長林真理子出身這裡","en":"Novelist Mariko Hayashi, a Naoki Prize winner and chair of Nihon University, is from here.","ja":"直木賞作家で日本大学理事長の林真理子の出身地"},{"k":"record","zh":"富士急樂園的「高飛車」以 121 度落下角，曾獲金氏認證為世界最陡雲霄飛車","en":"Fuji-Q Highland's Takabisha, with a 121° drop, was certified by Guinness as the world's steepest roller coaster.","ja":"富士急ハイランドの「高飛車」は最大落下角121度で、世界一急なコースターとしてギネス認定された"},{"k":"life","zh":"明明不靠海，縣廳所在地每戶的蛤蜊支出卻是全國第一的常客","en":"Though landlocked, the capital is a regular No. 1 in household spending on asari clams.","ja":"海なし県なのに、県庁所在地のあさり支出額は全国1位の常連"},{"k":"life","zh":"「吉田烏龍麵」麵條極硬，上面放的是燙高麗菜和馬肉","en":"Yoshida udon has extremely firm noodles topped with boiled cabbage and horse meat.","ja":"「吉田のうどん」は麺がとても硬く、ゆでキャベツと馬肉をのせる"}],
"JP-20":[{"k":"symbol","zh":"縣樹是高原上常見的白樺","en":"Its prefectural tree is the white birch, common in its highlands.","ja":"県の木は高原に多いシラカバ"},{"k":"people","zh":"以圓點南瓜聞名的前衛藝術家草間彌生出身松本","en":"Avant-garde artist Yayoi Kusama, famous for her polka-dot pumpkins, was born in Matsumoto.","ja":"水玉のカボチャで知られる前衛芸術家・草間彌生は松本市出身"},{"k":"people","zh":"大坂之陣被譽為「日本第一兵」的真田幸村，真田家的根據地在上田","en":"The Sanada clan of Yukimura, hailed as 'Japan's finest warrior' at the Siege of Osaka, was based in Ueda.","ja":"大坂の陣で「日本一の兵」と称された真田幸村の真田氏は、上田が本拠地"},{"k":"work","zh":"細田守動畫《夏日大作戰》以上田市一個大家族的老宅為舞台","en":"Mamoru Hosoda's Summer Wars is set at a big family's old house in Ueda.","ja":"細田守監督『サマーウォーズ』の舞台は上田市の旧家"},{"k":"festival","zh":"野澤溫泉的「道祖神火祭」：男人們守住高大的木造社殿，抵擋拿火把的村民猛攻","en":"At Nozawa Onsen's Dōsojin fire festival, men defend a tall wooden shrine from torch-wielding villagers.","ja":"野沢温泉の道祖神祭りでは、社殿を守る男たちと松明で火を放つ村人が激しくぶつかる"},{"k":"record","zh":"博物館與美術館的數量全國最多","en":"It has more museums and art galleries than any other prefecture.","ja":"博物館・美術館の数が全国最多"},{"k":"life","zh":"縣民幾乎人人都會唱縣歌《信濃之國》","en":"Almost everyone here can sing the prefectural song 'Shinano no Kuni'.","ja":"ほとんどの県民が県歌『信濃の国』を歌える"},{"k":"life","zh":"伊那地方有吃昆蟲的習慣：蜂之子、蝗蟲，甚至水生昆蟲「ざざむし」","en":"In the Ina area, people eat insects: bee larvae, locusts, even aquatic 'zazamushi'.","ja":"伊那地方には、蜂の子やイナゴ、ざざむしなど昆虫を食べる文化がある"}],
"JP-21":[{"k":"symbol","zh":"縣樹是「一位」（紅豆杉），飛驒的「一位一刀雕」就是用它刻的","en":"Its prefectural tree is the Japanese yew (ichii), the wood used for Hida's single-blade carvings.","ja":"県の木はイチイ。飛騨の一位一刀彫の材料になる"},{"k":"work","zh":"動畫電影《你的名字》中「系守町」的原型之一是飛驒市","en":"Hida City is one of the models for Itomori, the town in the film Your Name.","ja":"映画『君の名は。』の糸守町のモデルのひとつは飛騨市"},{"k":"work","zh":"動畫電影《聲之形》以大垣市為舞台","en":"The anime film A Silent Voice is set in Ōgaki.","ja":"映画『聲の形』の舞台は大垣市"},{"k":"people","zh":"二戰時發放「生命簽證」救了約六千名猶太人的外交官杉原千畝出身這裡","en":"Diplomat Chiune Sugihara, whose 'visas for life' saved some 6,000 Jews in WWII, was born here.","ja":"「命のビザ」で約6千人のユダヤ人を救った外交官・杉原千畝の出身地"},{"k":"festival","zh":"春秋兩季舉行的高山祭，名列日本三大美祭","en":"The Takayama Festival, held each spring and autumn, ranks among Japan's three most beautiful festivals.","ja":"春と秋の高山祭は日本三大美祭のひとつ"},{"k":"life","zh":"縣廳所在地每戶的咖啡廳消費，曾連續 4 年全國第一","en":"Households in the capital once ranked No. 1 in Japan for café spending four years running.","ja":"県庁所在地の1世帯あたり喫茶代は、4年連続全国1位になったことがある"},{"k":"record","zh":"郡上八幡被稱為食品模型的發祥地，業界龍頭岩崎瀧三就是這裡人","en":"Gujō Hachiman is called the birthplace of plastic food samples; industry pioneer Takizō Iwasaki came from there.","ja":"郡上八幡は食品サンプル発祥の地とされ、業界最大手を築いた岩崎瀧三の故郷"},{"k":"people","zh":"發動本能寺之變的明智光秀，據傳出身這裡的美濃地方","en":"Akechi Mitsuhide, who betrayed Oda Nobunaga at Honnō-ji, is said to have been born in the Mino area here.","ja":"本能寺の変を起こした明智光秀は、美濃の出身とされる"}],
"JP-22":[{"k":"symbol","zh":"縣鳥是三光鳥，叫聲聽起來像日文的「月、日、星」","en":"Its prefectural bird is the paradise flycatcher, whose call sounds like 'moon, sun, star' in Japanese.","ja":"県の鳥サンコウチョウは「ツキヒーホシ」と聞こえる声で鳴く"},{"k":"work","zh":"動畫《Love Live! Sunshine!!》以沼津的內浦為舞台","en":"The anime Love Live! Sunshine!! is set in Uchiura, Numazu.","ja":"アニメ『ラブライブ!サンシャイン!!』の舞台は沼津市内浦"},{"k":"people","zh":"豐田集團的創始人豐田佐吉，其實出身這裡的湖西","en":"Toyota group founder Sakichi Toyoda was actually born in Kosai here.","ja":"トヨタグループの創始者・豊田佐吉は、実はここの湖西市出身"},{"k":"festival","zh":"濱松祭以巨大風箏互相割線的「風箏大戰」聞名，起源是慶祝長子誕生","en":"The Hamamatsu Festival is famous for kite battles, rooted in celebrating the birth of first sons.","ja":"浜松まつりの凧揚げ合戦は、長男の誕生を祝う初凧が起源"},{"k":"origin","zh":"縣廳所在地原名「府中」，明治時代因為音近「不忠」而改名","en":"The capital was once called Fuchū; in the Meiji era it was renamed because 'Fuchū' sounds like 'disloyal'.","ja":"県庁所在地の旧名「府中」は「不忠」に通じるとして、明治に改名された"},{"k":"sport","zh":"曾三度奪得 J 聯盟冠軍的磐田喜悅隊以這裡為主場","en":"Júbilo Iwata, three-time J.League champions, are based here.","ja":"Jリーグで3度優勝したジュビロ磐田の本拠地"},{"k":"life","zh":"濱松市年年和宇都宮市爭奪「每戶餃子消費額」全國第一","en":"Hamamatsu and Utsunomiya battle every year for Japan's top household spending on gyoza.","ja":"浜松市は宇都宮市と毎年「餃子の支出額日本一」を争う"},{"k":"record","zh":"大井川上的蓬萊橋長 897 公尺，獲金氏認證為世界最長木造步道橋","en":"Hōrai Bridge over the Ōi River, 897 m long, is Guinness-certified as the world's longest wooden footbridge.","ja":"大井川の蓬莱橋は全長897mで、世界一長い木造歩道橋としてギネス認定"}],
"JP-23":[{"k":"symbol","zh":"縣花是燕子花（カキツバタ），《伊勢物語》在八橋以它為題作歌","en":"Its prefectural flower is the rabbit-ear iris, the subject of a famous poem at Yatsuhashi in the Tales of Ise.","ja":"県の花はカキツバタ。『伊勢物語』の八橋の歌で知られる"},{"k":"people","zh":"美日職棒傳奇鈴木一朗出身這裡的豐山町","en":"Baseball legend Ichiro Suzuki is from Toyoyama here.","ja":"日米で活躍したイチローは豊山町出身"},{"k":"work","zh":"2022 年開幕的吉卜力公園，蓋在長久手的愛・地球博紀念公園裡","en":"Ghibli Park, opened in 2022, sits inside the Expo 2005 memorial park in Nagakute.","ja":"2022年開業のジブリパークは、長久手市の愛・地球博記念公園の中にある"},{"k":"festival","zh":"國府宮「裸祭」上，數千名裸男推擠著想摸到「神男」來消災","en":"At Kōnomiya's Naked Festival, thousands of nearly naked men scramble to touch the 'shin-otoko' to ward off bad luck.","ja":"国府宮はだか祭では、大勢の裸男が厄を落とそうと神男に触れようともみ合う"},{"k":"origin","zh":"名字源自《萬葉集》歌詠的海邊潮灘「年魚市潟（あゆちがた）」","en":"The name comes from 'Ayuchi-gata', a tidal flat sung of in the Man'yōshū.","ja":"名は『万葉集』に詠まれた「年魚市潟（あゆちがた）」に由来"},{"k":"sport","zh":"職棒中日龍的主場在這裡","en":"The Chunichi Dragons baseball team plays its home games here.","ja":"プロ野球・中日ドラゴンズの本拠地"},{"k":"life","zh":"點咖啡就附吐司和水煮蛋的「早餐服務」，據說起源於一宮市","en":"The 'morning service', free toast and egg with your coffee, is said to have started in Ichinomiya.","ja":"コーヒーにトーストやゆで卵がつく「モーニング」は一宮市発祥とされる"},{"k":"record","zh":"菊花產量全國第一，渥美半島夜裡點燈讓菊花延後開花","en":"It grows the most chrysanthemums in Japan; on the Atsumi Peninsula, lights at night delay their blooming.","ja":"菊の生産量全国1位。渥美半島では夜に電照して開花を遅らせる"}],
"JP-24":[{"k":"symbol","zh":"縣樹是「神宮杉」","en":"Its prefectural tree is the 'Jingū cedar'.","ja":"県の木は神宮スギ"},{"k":"symbol","zh":"縣鳥是在海岸沙灘上築巢的白千鳥（シロチドリ）","en":"Its prefectural bird is the Kentish plover, which nests on sandy beaches.","ja":"県の鳥は砂浜に巣をつくるシロチドリ"},{"k":"people","zh":"奧運女子角力三連霸的吉田沙保里出身這裡","en":"Wrestler Saori Yoshida, three-time Olympic champion, is from here.","ja":"五輪3連覇の女子レスリング・吉田沙保里の出身地"},{"k":"people","zh":"電影導演小津安二郎的少年時期在松阪度過","en":"Film director Yasujirō Ozu spent his boyhood in Matsusaka.","ja":"映画監督・小津安二郎は少年時代を松阪で過ごした"},{"k":"festival","zh":"桑名的「石取祭」數十台祭車一起敲鉦打鼓，號稱「日本最吵的祭典」","en":"At Kuwana's Ishidori Festival, dozens of floats pound gongs and drums at once: 'Japan's noisiest festival'.","ja":"桑名の石取祭は祭車の鉦と太鼓を一斉に打ち鳴らし「日本一やかましい祭」と呼ばれる"},{"k":"origin","zh":"傳說日本武尊疲憊地說「我的腳像折了好幾層的年糕」，成了名字由來","en":"Legend says an exhausted Yamato Takeru complained his legs felt folded like layered rice cakes, giving the name.","ja":"ヤマトタケルが疲れ果て「足が幾重にも曲がった餅のようだ」と言った伝説が名の由来"},{"k":"record","zh":"長島溫泉樂園的「鋼龍2000」全長 2479 公尺，曾是世界最長的雲霄飛車","en":"Steel Dragon 2000 at Nagashima Spa Land, 2,479 m long, was once the world's longest roller coaster.","ja":"ナガシマスパーランドの「スチールドラゴン2000」は全長2479mで、かつて世界最長"},{"k":"work","zh":"描寫都市青年到深山當林業學徒的電影《哪啊哪啊～神去村》，在這裡的美杉拍攝","en":"The film Wood Job!, about a city youth apprenticed to foresters, was shot in the Misugi area here.","ja":"林業見習いを描く映画『WOOD JOB!』は、ここの美杉地区で撮影された"}],
"JP-25":[{"k":"symbol","zh":"縣鳥是擅長潛水的小鸊鷉（カイツブリ）","en":"Its prefectural bird is the little grebe, a small diving waterbird.","ja":"県の鳥は潜水が得意なカイツブリ。"},{"k":"people","zh":"戰國武將石田三成出生在這裡的長濱一帶","en":"Sengoku warlord Ishida Mitsunari was born here, in today's Nagahama.","ja":"戦国武将・石田三成は現在の長浜市石田町の生まれ。"},{"k":"work","zh":"動畫《K-ON！輕音部》高中的原型是這裡的豐鄉小學舊校舍","en":"The old Toyosato Elementary School here was the model for the high school in the anime K-On!","ja":"アニメ『けいおん!』の高校のモデルは豊郷小学校旧校舎。"},{"k":"sport","zh":"電視節目「鳥人間大賽」的人力飛機比賽在這裡的彥根湖畔舉行","en":"The TV Birdman Rally, a human-powered flight contest, is held on the lakeshore in Hikone.","ja":"人力飛行機の「鳥人間コンテスト」は彦根市の湖岸が会場。"},{"k":"festival","zh":"長濱曳山祭由孩童在山車舞台上演歌舞伎，列入聯合國非遺","en":"At the Nagahama Hikiyama Festival, children perform kabuki on float stages; it is UNESCO-listed.","ja":"長浜曳山祭では曳山の舞台で子ども歌舞伎を演じる。ユネスコ無形文化遺産。"},{"k":"record","zh":"伊吹山 1927 年積雪 11.82 公尺，至今仍是世界最深積雪紀錄","en":"Mt. Ibuki recorded 11.82 m of snow in 1927, still the world's deepest snow on record.","ja":"伊吹山は1927年に積雪1182cmを記録、今も破られていない世界記録。"},{"k":"life","zh":"路邊「衝出男孩」交通安全看板 1973 年起源於這裡","en":"The 'jumping-out boy' child-safety signboards originated here in 1973.","ja":"交通安全の看板「飛び出し坊や」は1973年にここで生まれた。"},{"k":"record","zh":"2020 年男性平均壽命 82.73 歲，全國第一","en":"Men here had Japan's longest life expectancy in 2020: 82.73 years.","ja":"2020年の男性の平均寿命は82.73歳で全国1位。"}],
"JP-26":[{"k":"work","zh":"動畫《吹響吧！上低音號》以作者故鄉、這裡的宇治為舞台","en":"The anime Sound! Euphonium is set in Uji here, the author's hometown.","ja":"アニメ『響け!ユーフォニアム』の舞台は作者の地元・宇治市。"},{"k":"life","zh":"市中心地址用「上ル（往北）、下ル（往南）」等方向詞標示","en":"Downtown addresses use direction words such as agaru (go north) and sagaru (go south) from street crossings.","ja":"中心部の住所は通り名に「上ル・下ル・西入ル」と方向を付けて表す。"},{"k":"origin","zh":"名字的兩個字都是「首都」的意思","en":"Both characters of its name mean 'capital'.","ja":"名前の2文字はどちらも「みやこ（首都）」を意味する。"},{"k":"record","zh":"1869 年居民自建 64 所「番組小學校」，比國家學制更早，是日本最早的學區制小學","en":"In 1869 locals founded 64 'bangumi' schools, Japan's first school-district elementary schools, before the national system.","ja":"1869年に64の番組小学校が開校。学制より早い日本初の学区制小学校。"},{"k":"record","zh":"1895 年日本第一條營業用電車（路面電車）在這裡通車","en":"Japan's first commercial electric streetcar began running here in 1895.","ja":"1895年、日本初の営業用電車（路面電車）がここで開業した。"},{"k":"sport","zh":"每年 12 月的全國高中驛傳（長跑接力）都在這裡的街道舉行","en":"Every December the national high school ekiden relay race is run through its streets.","ja":"毎年12月の全国高校駅伝は、この街の「都大路」が舞台。"},{"k":"festival","zh":"時代祭的遊行從明治維新開始，一路倒著走回八世紀","en":"The Jidai Matsuri parade runs history backward, from the Meiji Restoration to the 8th century.","ja":"時代祭の行列は明治維新から始まり、時代をさかのぼって延暦へ。"},{"k":"people","zh":"幕末的新選組在這裡的壬生設屯所，因池田屋事件成名","en":"The Shinsengumi were based in Mibu here and rose to fame through the Ikedaya Incident.","ja":"新選組は壬生に屯所を置き、池田屋事件で名を上げた。"}],
"JP-27":[{"k":"symbol","zh":"宣傳吉祥物是一隻伯勞鳥，叫「もずやん」","en":"Its PR mascot is a shrike character named Mozuyan.","ja":"PRキャラクターはモズがモチーフの「もずやん」。"},{"k":"sport","zh":"全國高中橄欖球大賽的會場「花園」被稱為橄欖球聖地","en":"Hanazono, home of the national high school rugby tournament, is called the sacred ground of rugby.","ja":"全国高校ラグビーの会場「花園」はラグビーの聖地と呼ばれる。"},{"k":"people","zh":"《龍馬行》作者司馬遼太郎在這裡出生，晚年也住在這裡","en":"Novelist Ryotaro Shiba, author of Ryoma ga Yuku, was born here and spent his later life here.","ja":"『竜馬がゆく』の司馬遼太郎はここで生まれ、晩年もここで暮らした。"},{"k":"life","zh":"關西搭電扶梯「站右邊、左邊讓人走」的習慣，1967 年起於這裡的阪急梅田站","en":"Kansai's habit of standing on the right of escalators began at Hankyu Umeda Station here in 1967.","ja":"エスカレーターで左を空ける関西の習慣は、1967年の阪急梅田駅から。"},{"k":"record","zh":"迴轉壽司 1958 年誕生於這裡的布施，靈感來自啤酒工廠輸送帶","en":"Conveyor-belt sushi was born here in Fuse in 1958, inspired by beer factory conveyors.","ja":"回転寿司は1958年に布施で誕生。ビール工場のベルトコンベアが発想源。"},{"k":"festival","zh":"岸和田地車祭的看點是拉著沉重山車全速甩過街角的「やりまわし」","en":"Kishiwada's Danjiri Festival is famed for yarimawashi, swinging heavy floats around corners at full speed.","ja":"岸和田だんじり祭の見せ場は、勢いのまま角を曲がる「やりまわし」。"},{"k":"origin","zh":"地名原本的「坂」字可拆成「土」「反」，被嫌像歸於塵土不吉而改字","en":"The 'slope' character in its name was changed because it could be read as 'return to earth', a bad omen.","ja":"地名の「坂」は「土に反る」と読めて縁起が悪いとされ、字が改められた。"}],
"JP-28":[{"k":"symbol","zh":"縣花是野生的菊花「野路菊（ノジギク）」","en":"Its prefectural flower is the nojigiku, a wild chrysanthemum.","ja":"県の花は野生の菊・ノジギク。"},{"k":"record","zh":"日本最古老的高爾夫球場 1903 年由英國商人建在六甲山上","en":"Japan's oldest golf course was built on Mt. Rokko by a British merchant in 1903.","ja":"日本最古のゴルフ場は1903年に英国人グルームが六甲山上に開いた。"},{"k":"people","zh":"漫畫之神手塚治虫在這裡的寶塚住了約 20 年，當地有他的紀念館","en":"Manga legend Osamu Tezuka spent about 20 years in Takarazuka here, home to his memorial museum.","ja":"手塚治虫は宝塚で約20年を過ごし、記念館がある。"},{"k":"work","zh":"動畫電影《螢火蟲之墓》中，兄妹住進西宮池畔的防空洞","en":"In Grave of the Fireflies, the siblings move into a shelter by a pond in Nishinomiya.","ja":"『火垂るの墓』の兄妹は西宮の池のほとりの防空壕で暮らした。"},{"k":"festival","zh":"姬路的「灘之喧嘩祭」把三座神轎互相猛撞","en":"At the Nada Fighting Festival in Himeji, three portable shrines are smashed into each other.","ja":"姫路の「灘のけんか祭り」は3基の神輿を激しくぶつけ合う。"},{"k":"life","zh":"姬路一家公司生產全日本約七成的國產火柴","en":"One company in Himeji makes about 70% of Japan's domestically produced matches.","ja":"姫路市の日東社が国産マッチの約7割を製造している。"},{"k":"record","zh":"古墳數量 18,351 座，全國最多","en":"It has 18,351 ancient burial mounds, the most of any prefecture.","ja":"古墳の数は18,351か所で全国1位。"}],
"JP-29":[{"k":"symbol","zh":"吉祥物是長著鹿角的童子「遷都君（せんとくん）」","en":"Its mascot Sento-kun is a child with deer antlers.","ja":"マスコットは鹿の角が生えた童子「せんとくん」。"},{"k":"people","zh":"傳說獨眼的劍豪柳生十兵衛出生在這裡的柳生庄","en":"Yagyu Jubei, the swordsman of one-eyed legend, was born in Yagyu village here.","ja":"隻眼の剣豪伝説で知られる柳生十兵衛は柳生庄の生まれ。"},{"k":"work","zh":"小說《鹿男》：到這裡女校代課的老師，被公園的鹿開口交付使命","en":"In the novel Shikaotoko Aoniyoshi, a substitute teacher at a girls' school here gets orders from a talking deer.","ja":"小説『鹿男あをによし』は女子高に赴任した教師が鹿に使命を託される話。"},{"k":"festival","zh":"東大寺二月堂的「汲水」法會自 752 年起從未中斷","en":"Todaiji's Omizutori rite at Nigatsudo has been held every year without a break since 752.","ja":"東大寺二月堂のお水取りは752年から一度も途絶えていない。"},{"k":"origin","zh":"地名一說來自日語「把土地整平」的動詞","en":"One theory derives the name from a Japanese verb meaning 'to level the ground'.","ja":"地名は「土地を平らにする」という意味の言葉が由来という説がある。"},{"k":"record","zh":"這裡的天理市是 21 世紀日本唯一以宗教命名的市","en":"Tenri here is the only city in 21st-century Japan named after a religion.","ja":"天理市は宗教名を市名にした21世紀の日本で唯一の市。"},{"k":"life","zh":"公園裡的野生鹿是國家天然紀念物，會鞠躬討鹿仙貝","en":"The park's wild deer are a national natural monument and bow to beg for deer crackers.","ja":"公園の鹿は国の天然記念物で、おじぎして鹿せんべいをねだる。"},{"k":"sport","zh":"《日本書紀》裡當麻蹴速與野見宿禰的角力，被視為相撲起源","en":"The Nihon Shoki bout between Taima no Kehaya and Nomi no Sukune, seen as sumo's origin, is linked to here.","ja":"相撲の起源とされる當麻蹴速と野見宿禰の力比べの伝承地。"}],
"JP-30":[{"k":"symbol","zh":"縣樹是烏岡櫟（ウバメガシ），也是備長炭的原料","en":"Its prefectural tree is the ubame oak, the raw material of binchotan charcoal.","ja":"県の木はウバメガシ、備長炭の原料。"},{"k":"people","zh":"江戶幕府八代將軍德川吉宗，原本是這裡的紀州藩主","en":"Tokugawa Yoshimune, the 8th shogun, was lord of the Kishu domain here before taking power.","ja":"8代将軍・徳川吉宗はもともと紀州藩主だった。"},{"k":"sport","zh":"日本足協標誌上的三足烏「八咫烏」，是這裡熊野本宮大社的神使","en":"The three-legged crow on the Japan Football Association emblem is the messenger of the Kumano deity here.","ja":"日本サッカー協会のシンボル・八咫烏は熊野の神の使い。"},{"k":"work","zh":"動畫《夏日重現》的日都島，原型是這裡的無人島友島","en":"Hitogashima in Summer Time Rendering is modeled on Tomogashima, an uninhabited island here.","ja":"『サマータイムレンダ』の日都ヶ島のモデルは無人島の友ヶ島。"},{"k":"festival","zh":"那智火祭中，12 支大火把繞著石階，把火星灑向扇神轎","en":"At the Nachi Fire Festival, 12 huge torches circle the stone steps, showering sparks on fan-shaped mikoshi.","ja":"那智の火祭では大松明12本が石段を回り、扇神輿に火の粉を浴びせる。"},{"k":"record","zh":"那智勝浦的「ぶつぶつ川」全長 13.5 公尺，是日本最短的法定河川","en":"The Butsubutsu River in Nachikatsuura is just 13.5 m long, Japan's shortest official river.","ja":"那智勝浦町のぶつぶつ川は全長13.5m、日本一短い法定河川。"},{"k":"record","zh":"北山村是被奈良、三重包圍的飛地，全日本唯一","en":"Kitayama village is an exclave surrounded by Nara and Mie, the only such municipality in Japan.","ja":"北山村は奈良・三重に囲まれた飛び地で、日本で唯一。"},{"k":"life","zh":"這裡的拉麵店桌上擺著鯖魚押壽司，吃幾個自己報數結帳","en":"Ramen shops here leave mackerel pressed sushi on the table; you report how many you ate when paying.","ja":"ラーメン店の卓上に早ずしがあり、食べた数を自己申告で払う。"}],
"JP-31":[{"k":"symbol","zh":"縣鳥是鴛鴦","en":"Its prefectural bird is the mandarin duck.","ja":"県の鳥はオシドリ。"},{"k":"people","zh":"2024 年就任首相的石破茂在這裡長大，選區也在這裡","en":"Shigeru Ishiba, who became prime minister in 2024, grew up here and represents a district here.","ja":"2024年に首相となった石破茂はここで育ち、選挙区もここ。"},{"k":"work","zh":"游泳動畫《Free!》的岩鳶町，原型是這裡的岩美町","en":"Iwatobi in the swimming anime Free! is based on the town of Iwami here.","ja":"水泳アニメ『Free!』の岩鳶町のモデルは岩美町。"},{"k":"festival","zh":"傘舞祭 2014 年以 1688 人同跳，獲金氏認證為「世界最大傘舞」","en":"Its Shan Shan Festival set a Guinness record in 2014 for the largest umbrella dance, with 1,688 dancers.","ja":"しゃんしゃん祭は2014年、1688人で「世界最大の傘踊り」とギネス認定。"},{"k":"origin","zh":"名字源自古代替朝廷捕捉水鳥納貢的部民","en":"The name comes from an ancient guild that caught waterbirds as tribute for the imperial court.","ja":"名前は朝廷のために鳥を捕らえて納めた古代の部民に由来する。"},{"k":"record","zh":"2013 年全國第一個通過把手語當作語言的條例","en":"In 2013 it passed Japan's first ordinance recognizing sign language as a language.","ja":"2013年、手話を言語とする条例を全国で初めて可決した。"},{"k":"life","zh":"還沒有星巴克時，知事說「沒有Sutaba但有Sunaba（沙丘）」，催生了「沙場咖啡」","en":"With no Starbucks yet, the governor joked 'no Sutaba, but we have the Sunaba (sand dunes)', inspiring Sunaba Coffee.","ja":"スタバがない頃、知事の「スナバはある」発言から「すなば珈琲」が誕生。"},{"k":"life","zh":"每年秋冬螃蟹季，縣政府會把縣名的一個字換成「蟹」來宣傳","en":"Every autumn-to-winter crab season, the prefecture rebrands itself by swapping a character of its name for 'crab'.","ja":"秋冬のカニの季節には県名の一字を「蟹」に替える改名キャンペーンを行う。"}],
"JP-32":[{"k":"symbol","zh":"縣魚是飛魚","en":"Its prefectural fish is the flying fish.","ja":"県の魚はトビウオ。"},{"k":"people","zh":"歌手竹內瑪莉亞出生在出雲大社旁的老字號旅館","en":"Singer Mariya Takeuchi was born into the family running an old inn near Izumo Taisha.","ja":"歌手の竹内まりやは出雲大社近くの老舗旅館・竹野屋の生まれ。"},{"k":"sport","zh":"網球名將錦織圭的故鄉","en":"Hometown of tennis star Kei Nishikori.","ja":"テニスの錦織圭の出身地。"},{"k":"work","zh":"松本清張《砂之器》的破案關鍵，是這裡的方言竟像東北腔","en":"In Seicho Matsumoto's Castle of Sand, the key clue is that a local dialect here sounds like Tohoku speech.","ja":"松本清張『砂の器』は、東北弁に似た出雲の方言と「亀嵩」が鍵。"},{"k":"festival","zh":"船祭「ホーランエンヤ」每 10 年才辦一次，是日本三大船神事之一","en":"Horan Enya, held only once every 10 years, is one of Japan's three great boat rituals.","ja":"ホーランエンヤは10年に一度、日本三大船神事のひとつ。"},{"k":"record","zh":"《出雲國風土記》是唯一幾乎完整流傳至今的風土記","en":"The Izumo Fudoki is the only ancient provincial gazetteer surviving almost complete.","ja":"『出雲国風土記』は唯一ほぼ完本で残る風土記。"},{"k":"record","zh":"每 10 萬人中的百歲人瑞人數連續多年全國第一","en":"It has had Japan's most centenarians per 100,000 people for many years running.","ja":"人口10万人あたりの100歳以上の人数が長年全国1位。"},{"k":"origin","zh":"縣名據說是《出雲國風土記》中把土地拉來造國的神明所取","en":"The name was reportedly given by the god who 'pulled land' to build the province in the Izumo Fudoki.","ja":"県名は『出雲国風土記』で国引きの神・八束水臣津野命が名付けたと伝わる。"}],
"JP-33":[{"k":"people","zh":"B'z 主唱稻葉浩志的故鄉是這裡的津山","en":"B'z vocalist Koshi Inaba comes from Tsuyama here.","ja":"B'zの稲葉浩志は津山市出身。"},{"k":"work","zh":"橫溝正史《八墓村》的發想來自這裡 1938 年的真實事件","en":"Seishi Yokomizo's The Village of Eight Graves was inspired by a real 1938 incident here.","ja":"横溝正史『八つ墓村』は1938年にここで起きた事件が発想源。"},{"k":"festival","zh":"西大寺會陽中，裸男爭搶從窗口投下的「寶木」，搶到的就是福男","en":"At Saidaiji Eyo, nearly naked men fight for sacred sticks thrown from a window; the winner is the year's lucky man.","ja":"西大寺会陽では裸の男たちが窓から投下される宝木を奪い合う。"},{"k":"origin","zh":"名字來自旭川河口的一座小丘，宇喜多直家在丘上築城","en":"Its name comes from a small hill at the Asahi River mouth where Ukita Naoie built his castle.","ja":"名前は旭川河口の丘の名で、宇喜多直家がそこに城を築いた。"},{"k":"record","zh":"2020 年女性平均壽命 88.29 歲，全國第一","en":"Women here had Japan's longest life expectancy in 2020: 88.29 years.","ja":"2020年の女性の平均寿命は88.29歳で全国1位。"},{"k":"record","zh":"吉備津神社本殿有前後並排的兩個屋頂，是全國唯一的「吉備津造」","en":"Kibitsu Shrine's main hall, with two roofs joined front to back, is the only one of its style in Japan.","ja":"吉備津神社の本殿は全国唯一の比翼入母屋造（吉備津造）。"},{"k":"sport","zh":"職棒名投手、名教頭星野仙一出身這裡的倉敷","en":"Baseball star and manager Senichi Hoshino came from today's Kurashiki here.","ja":"野球の星野仙一は現在の倉敷市の出身。"},{"k":"work","zh":"動畫電影《午睡公主》以瀨戶大橋旁的下津井為舞台","en":"The anime film Napping Princess is set in Shimotsui at the foot of the Seto Ohashi Bridge.","ja":"映画『ひるね姫』の舞台は瀬戸大橋のたもとの下津井。"}],
"JP-34":[{"k":"sport","zh":"J聯盟「Sanfrecce」隊名是日文「三」加義大利文「箭」，取自毛利元就三支箭","en":"J.League club Sanfrecce blends Japanese 'san' (three) and Italian 'frecce' (arrows), after Mori Motonari.","ja":"サンフレッチェは「三」と伊語の「矢」の合成、毛利元就の三本の矢から。"},{"k":"sport","zh":"職棒鯉魚隊沒有母公司，草創期靠球迷把錢投進酒桶撐過危機","en":"The Carp began as a citizens' team with no parent company and survived on fans' 'barrel donations'.","ja":"カープは親会社のない市民球団が源流で、樽募金で危機を乗り越えた。"},{"k":"people","zh":"電音女團 Perfume 三位成員都是這裡出身","en":"All three members of the techno-pop group Perfume are from here.","ja":"テクノポップユニットPerfumeは3人とも県出身。"},{"k":"work","zh":"動畫電影《謝謝你，在世界的角落找到我》主角從江波嫁到軍港吳","en":"In the film In This Corner of the World, the heroine marries from Eba into a family in the naval port of Kure.","ja":"『この世界の片隅に』の主人公すずは江波から軍港・呉へ嫁ぐ。"},{"k":"life","zh":"盂蘭盆節會在墓前供上彩色紙糊、牽牛花形的「盆燈籠」","en":"At Obon, families here set colorful paper lanterns shaped like morning glories at graves.","ja":"お盆には色紙で作った朝顔形の盆灯籠を墓に供える。"},{"k":"origin","zh":"一說地名是從毛利氏祖先與協助選城址的武將名字中各取一字","en":"One theory says the name takes one character each from a Mori ancestor and the officer who chose the castle site.","ja":"地名は毛利氏の祖先と城地を選んだ武将の名から一字ずつ取ったという説がある。"},{"k":"festival","zh":"6 月的「とうかさん」祭是當地人一年中第一次穿浴衣的日子","en":"The Tokasan festival in June marks the day locals put on yukata for the first time each year.","ja":"6月の「とうかさん」は、その年の浴衣の着始めの祭り。"},{"k":"life","zh":"宮島整座島是神域，島上至今連一座墳墓都沒有","en":"Miyajima is considered sacred, and to this day there is not a single grave on the island.","ja":"宮島は島全体が神域で、今も墓が1基もない。"}],
"JP-35":[{"k":"symbol","zh":"縣花是夏蜜柑的花","en":"Its prefectural flower is the natsumikan (summer orange) blossom.","ja":"県の花は夏みかんの花。"},{"k":"people","zh":"詩人中原中也出生在這裡的湯田溫泉","en":"Poet Chuya Nakahara was born at Yuda Onsen here.","ja":"詩人・中原中也は湯田温泉の生まれ。"},{"k":"people","zh":"UNIQLO 的母公司迅銷集團總部設在這裡","en":"Fast Retailing, the company behind Uniqlo, has its head office here.","ja":"ユニクロを展開するファーストリテイリングの本社がある。"},{"k":"festival","zh":"先帝祭裡扮成花魁的太夫踩外八字遊行，追悼沉海的安德天皇","en":"At the Sentei Festival, women dressed as courtesans parade in memory of Emperor Antoku, who drowned at sea.","ja":"先帝祭では花魁姿の太夫が外八文字で練り歩き、安徳天皇をしのぶ。"},{"k":"record","zh":"全國獨有的牛品種「無角和牛」是這裡培育出來的","en":"Mukaku Wagyu, a hornless cattle breed found nowhere else in Japan, was developed here.","ja":"全国唯一の無角和牛は県が誕生させた品種。"},{"k":"life","zh":"當地為了討吉利，把河豚叫「ふく」（福）","en":"Locals call pufferfish 'fuku' (luck) instead of 'fugu' for good fortune.","ja":"フグは縁起をかついで「ふく」と呼ばれる。"},{"k":"life","zh":"路邊護欄漆成黃色，取自特產夏蜜柑的顏色","en":"Guardrails here are painted yellow after the local natsumikan orange.","ja":"ガードレールは特産の夏みかんにちなんだ黄色。"},{"k":"record","zh":"有紀錄可查的日本第一個聖誕節，1552 年在這裡舉行","en":"Japan's earliest recorded Christmas celebration was held here in 1552.","ja":"記録に残る日本初のクリスマスは1552年にここで行われた。"}],
"JP-36":[{"k":"people","zh":"創作歌手米津玄師的故鄉","en":"Hometown of singer-songwriter Kenshi Yonezu.","ja":"米津玄師の出身地。"},{"k":"people","zh":"作家瀨戶內寂聽出生在這裡的一家佛壇店","en":"Novelist and nun Jakucho Setouchi was born into a Buddhist altar shop here.","ja":"作家・瀬戸内寂聴は仏壇店の娘として生まれた。"},{"k":"festival","zh":"動漫祭典「Machi★Asobi」在這裡舉辦，長年由 ufotable 策劃","en":"The anime festival Machi Asobi, long produced by studio ufotable, is held here.","ja":"アニメの祭典「マチ★アソビ」の開催地。長くufotableが企画した。"},{"k":"sport","zh":"池田高中 1982 年夏、1983 年春連霸甲子園","en":"Ikeda High School won Koshien in summer 1982 and spring 1983 back to back.","ja":"池田高校は1982年夏・83年春の甲子園を連覇した。"},{"k":"record","zh":"弁天山標高 6.1 公尺，號稱日本最低的天然山","en":"Mt. Benten, 6.1 m tall, is said to be Japan's lowest natural mountain.","ja":"標高6.1mの弁天山は、自然の山として日本一低いとされる。"},{"k":"record","zh":"全國唯一沒有電車、只跑柴油車的縣，當地人把火車叫「汽車」","en":"It's the only prefecture with no electric trains, only diesel railcars, which locals call 'kisha'.","ja":"電車が走らず気動車だけの全国唯一の県で、鉄道を「汽車」と呼ぶ。"},{"k":"symbol","zh":"吉祥物是綠色柑橘頭的「酢橘君（すだちくん）」","en":"Its mascot is Sudachi-kun, a green citrus character.","ja":"マスコットキャラクターは「すだちくん」。"},{"k":"origin","zh":"古國名「阿波」源自北部盛產小米（粟）","en":"Its old province name, Awa, comes from the millet (awa) grown widely in the north.","ja":"旧国名「阿波」は北部に粟が多い「粟国」から。"}],
"JP-37":[{"k":"people","zh":"創辦雜誌《文藝春秋》的作家菊池寬出身這裡","en":"Writer Kan Kikuchi, founder of the magazine Bungeishunju, was born here.","ja":"『文藝春秋』を創刊した作家・菊池寛の出身地。"},{"k":"people","zh":"首相大平正芳出身這裡，因說話常「啊、嗚」被叫「啊嗚宰相」","en":"PM Masayoshi Ohira came from here; his 'ah, uh' speaking habit earned him the nickname 'Ah-Uh Premier'.","ja":"首相・大平正芳の出身地。「アーウー宰相」と呼ばれた。"},{"k":"sport","zh":"J聯盟球隊名結合當地名物「釜玉烏龍麵」與義大利文的「海」","en":"Its J.League club's name blends kamatama udon with 'mare', Italian for sea.","ja":"Jリーグのカマタマーレは「釜玉うどん」と伊語の「海」の合成。"},{"k":"work","zh":"電影《二十四隻眼睛》把女老師與 12 個學生的故事放在小豆島","en":"The film Twenty-Four Eyes set its story of a young teacher and 12 pupils on Shodoshima.","ja":"映画『二十四の瞳』で小豆島が女性教師と12人の教え子の舞台に。"},{"k":"work","zh":"電影《在世界的中心呼喊愛》主要在這裡的庵治町取景","en":"The film Crying Out Love, in the Center of the World was mainly shot in Aji here.","ja":"映画『世界の中心で、愛をさけぶ』のメインロケ地は庵治町。"},{"k":"life","zh":"2020 年的條例建議 18 歲以下打電玩每天以 60 分鐘為限","en":"A 2020 ordinance recommends under-18s limit video games to 60 minutes a day.","ja":"2020年の条例で、18歳未満のゲームは1日60分が目安に。"},{"k":"life","zh":"新年雜煮用白味噌，裡面放包紅豆餡的年糕","en":"Its New Year zoni soup is made with white miso and mochi stuffed with sweet bean paste.","ja":"正月の雑煮は白味噌仕立てで、あんこ入りの餅を入れる。"},{"k":"festival","zh":"每 3 年一次的瀨戶內國際藝術祭，以直島、豐島等島嶼為會場","en":"The Setouchi Triennale art festival, held every three years, centers on islands such as Naoshima and Teshima.","ja":"3年に一度の瀬戸内国際芸術祭は直島・豊島などの島々が会場。"}],
"JP-38":[{"k":"symbol","zh":"吉祥物「みきゃん」是橘子小狗，因為縣的形狀像奔跑的狗","en":"Its mascot Mikyan is an orange-dog, partly because the prefecture is shaped like a running dog.","ja":"マスコット「みきゃん」はみかんと犬。県の形が走る犬に似るのも理由。"},{"k":"origin","zh":"名字來自《古事記》中的女神名，是全國唯一以神名命名的縣","en":"Its name comes from a goddess in the Kojiki, making it the only prefecture named after a deity.","ja":"名前は『古事記』の女神の名で、神名を付けた全国唯一の県。"},{"k":"record","zh":"今治市的吉祥物「巴里桑」拿下 2012 年吉祥物大賽冠軍","en":"Imabari's mascot Barysan won the 2012 Yuru-chara Grand Prix.","ja":"今治市のバリィさんはゆるキャラグランプリ2012で優勝した。"},{"k":"work","zh":"日劇《東京愛情故事》結局，女主角把手帕綁在梅津寺站的欄杆上","en":"In the finale of Tokyo Love Story, Rika ties her handkerchief to the fence at Baishinji Station here.","ja":"『東京ラブストーリー』最終回、リカが梅津寺駅の柵にハンカチを結んだ。"},{"k":"work","zh":"道後溫泉本館是《神隱少女》湯屋的原型之一","en":"Dogo Onsen's main building is one of the models for the bathhouse in Spirited Away.","ja":"道後温泉本館は『千と千尋の神隠し』の油屋のモデルのひとつ。"},{"k":"work","zh":"《坂上之雲》的三位主角秋山兄弟與正岡子規都出身這裡","en":"The three heroes of Clouds Above the Hill, the Akiyama brothers and Masaoka Shiki, came from here.","ja":"『坂の上の雲』の主人公、秋山兄弟と正岡子規はここの出身。"},{"k":"festival","zh":"新居濱太鼓祭的太鼓台重約 2 噸，要 200 多人一起扛","en":"At the Niihama Taiko Festival, 2-ton drum floats are hoisted by more than 200 bearers.","ja":"新居浜太鼓祭りの太鼓台は重さ約2トン、200人以上で担ぐ。"},{"k":"life","zh":"宴會遊戲「野球拳」是這裡的伊予鐵棒球隊 1924 年在客場比賽後的宴會上首創的","en":"The party game yakyuken was invented in 1924 by a baseball team from here, at a banquet after an away game.","ja":"宴会芸「野球拳」は1924年、ここの伊予鉄野球部が遠征試合後の懇親会で始めたもの。"}],
"JP-39":[{"k":"symbol","zh":"縣鳥是八色鳥","en":"Its prefectural bird is the fairy pitta.","ja":"県の鳥はヤイロチョウ。"},{"k":"people","zh":"《麵包超人》作者柳瀨嵩在這裡長大，當地有麵包超人博物館","en":"Anpanman creator Takashi Yanase grew up here, home to the Anpanman Museum.","ja":"アンパンマンのやなせたかしはここで育ち、記念館がある。"},{"k":"work","zh":"吉卜力動畫《聽見濤聲》以這裡為舞台","en":"Studio Ghibli's Ocean Waves is set here.","ja":"ジブリ作品『海がきこえる』の舞台。"},{"k":"festival","zh":"「どろめ祭」比賽一口氣喝乾大杯清酒，男生要喝 1.8 公升","en":"At the Dorome Festival, contestants race to down huge cups of sake: 1.8 liters for men.","ja":"どろめ祭りでは男性1升、女性5合の酒を一気飲みして速さを競う。"},{"k":"origin","zh":"城址夾在兩河間常淹水，原名「河中」，後來改成同音的吉祥字","en":"The flood-prone castle site between two rivers was first named 'amid the rivers', later rewritten with luckier characters.","ja":"城地は川に挟まれ洪水が多く「河中山」と呼ばれ、のち同音の字に改めた。"},{"k":"record","zh":"1934 年室戶颱風登陸時氣壓 911.6 hPa，日本本土觀測史上最低","en":"The 1934 Muroto Typhoon made landfall at 911.6 hPa, the lowest ever recorded on Japan's main islands.","ja":"室戸台風は上陸時911.6hPa、本土上陸台風で観測史上最低。"},{"k":"life","zh":"週日街市從 1690 年延續至今，約 300 個攤位綿延約 1 公里","en":"Its Sunday street market has run since 1690, with about 300 stalls stretching some 1 km.","ja":"日曜市は1690年から続き、約300店が約1kmにわたって並ぶ。"}],
"JP-40":[{"k":"sport","zh":"職棒鷹隊 1989 年從大阪搬到這裡","en":"The Hawks pro baseball team moved here from Osaka in 1989.","ja":"ホークスは1989年に大阪から本拠地を移してきた。"},{"k":"people","zh":"藝人塔摩利的故鄉","en":"Hometown of TV host Tamori.","ja":"タモリの出身地。"},{"k":"people","zh":"《鬼滅之刃》作者吾峠呼世晴的故鄉","en":"Home of Koyoharu Gotouge, creator of Demon Slayer.","ja":"『鬼滅の刃』の作者・吾峠呼世晴の出身地。"},{"k":"festival","zh":"「博多咚打鼓」的起源是 1179 年開始的博多松囃子","en":"Hakata Dontaku traces its origin to the Hakata matsubayashi parade begun in 1179.","ja":"博多どんたくの起源は1179年に始まった博多松囃子。"},{"k":"origin","zh":"黑田長政以祖先故鄉備前（今岡山縣）的地名替城下町命名","en":"Kuroda Nagamasa named his castle town after his ancestral home in Bizen, in today's Okayama.","ja":"黒田長政が一族ゆかりの備前国の地名を城下町に付けた。"},{"k":"life","zh":"博多的承天寺立有「烏龍麵、蕎麥麵發祥地」石碑","en":"Jotenji temple in Hakata has a monument naming it the birthplace of udon and soba.","ja":"博多の承天寺に、うどん・そば発祥の碑がある。"},{"k":"record","zh":"夜間路邊攤「屋台」的數量日本第一","en":"It has more yatai street food stalls than anywhere else in Japan.","ja":"屋台の数が日本一。"},{"k":"life","zh":"機場離市中心超近，搭地鐵只要幾分鐘","en":"Its airport is so close to downtown that the subway gets you there in minutes.","ja":"空港が都心から近く、地下鉄で数分。"}],
"JP-41":[{"k":"symbol","zh":"縣鳥是喜鵲，當地也叫「勝鴉（カチガラス）」","en":"Its prefectural bird is the magpie, locally called kachigarasu.","ja":"県の鳥はカササギ（カチガラス）。"},{"k":"origin","zh":"縣名據說源自《風土記》中因大樟樹而被稱為「榮之國」的傳說","en":"The name is said to derive from the 'land of prosperity' in a Fudoki legend about a great camphor tree.","ja":"県名は『風土記』の楠の伝説にある「栄の国」に由来するとされる。"},{"k":"people","zh":"固力果創辦人江崎利一出身這裡，從當地牡蠣的肝醣得到靈感","en":"Glico founder Riichi Ezaki was born here and got his idea from glycogen in local oysters.","ja":"グリコ創業者・江崎利一の出身地。牡蠣のグリコーゲンが発想源。"},{"k":"work","zh":"有部動畫講殭屍少女組成偶像團體，為了讓這個縣更出名","en":"In one anime, zombie girls form an idol group to make this prefecture better known.","ja":"ゾンビの少女たちがご当地アイドルとして県を盛り上げるアニメの舞台。"},{"k":"work","zh":"藝人塙（はなわ）靠自嘲家鄉的同名歌曲登上紅白","en":"Comedian Hanawa reached NHK's Kohaku with a self-mocking song named after this prefecture.","ja":"はなわは自虐的な同名の歌でNHK紅白に出場した。"},{"k":"festival","zh":"唐津宮日祭有 14 台漆製曳山，包括一條巨大的紅鯛魚","en":"Karatsu Kunchi features 14 lacquered floats, including a giant red sea bream.","ja":"唐津くんちには巨大な鯛など乾漆の曳山が14台ある。"},{"k":"record","zh":"全國唯一兩個鄰縣彼此不相接的縣，福岡往長崎一定要經過這裡","en":"It's the only prefecture whose neighbors don't touch each other, so Fukuoka–Nagasaki trips pass through it.","ja":"隣の2県同士が接しない唯一の県で、福岡と長崎の行き来は必ず通る。"},{"k":"people","zh":"幕末明治的鍋島直正、佐野常民等七位偉人被稱為「七賢人」","en":"Seven Meiji-era greats, including Nabeshima Naomasa and Sano Tsunetami, are honored here as the 'Seven Sages'.","ja":"鍋島直正・佐野常民ら幕末明治の偉人7人は「七賢人」と呼ばれる。"}],
"JP-42":[{"k":"people","zh":"歌手、演員福山雅治的故鄉","en":"Hometown of singer-actor Masaharu Fukuyama.","ja":"福山雅治の出身地。"},{"k":"work","zh":"漫畫《元氣囝仔》講書法家被送到這裡的五島列島生活","en":"In the manga Barakamon, a calligrapher is sent to live on the Goto Islands here.","ja":"漫画『ばらかもん』は書道家が五島列島で暮らす物語。"},{"k":"work","zh":"電影《007：空降危機》反派的廢墟島「死城」，原型是這裡的軍艦島","en":"The villain's ruined island 'Dead City' in Skyfall was modeled on Hashima (Battleship Island) here.","ja":"映画『007 スカイフォール』の廃墟の島は端島（軍艦島）がモデル。"},{"k":"festival","zh":"宮日祭的招牌是「龍踊」，觀眾會喊「もってこーい」要求安可","en":"Kunchi's highlight is the dragon dance, with crowds shouting 'motte koi!' for an encore.","ja":"くんちの代表的な演し物は龍踊り。アンコールの掛け声は「もってこーい」。"},{"k":"origin","zh":"地名主流說法來自鎌倉時代一個御家人家族的姓氏","en":"The main theory says the name comes from the surname of a Kamakura-era warrior family.","ja":"地名は鎌倉時代の御家人一族の名に由来するとの説が主流。"},{"k":"sport","zh":"源自中國福建的龍舟競賽「ペーロン」，江戶時代就在這裡舉行","en":"Peron dragon-boat racing, from Fujian in China, has been held here since the Edo period.","ja":"福建由来の龍舟競漕「ペーロン」が江戸時代から行われている。"},{"k":"record","zh":"日本第一座保齡球館 1861 年開在這裡，6 月 22 日因此定為保齡球日","en":"Japan's first bowling alley opened here in 1861; Bowling Day, June 22, marks the date.","ja":"1861年に日本初のボウリング場が開業、6月22日は「ボウリングの日」。"},{"k":"record","zh":"壹岐的遺址出土了日本最古老的貓骨","en":"Japan's oldest cat bones were excavated from a site on Iki island here.","ja":"壱岐のカラカミ遺跡から日本最古のネコの骨が出土した。"}],
"JP-43":[{"k":"people","zh":"《航海王》作者尾田榮一郎的故鄉，地震後以魯夫名義捐 8 億日圓","en":"Home of One Piece creator Eiichiro Oda, who donated ¥800 million in Luffy's name after the earthquake.","ja":"『ONE PIECE』の尾田栄一郎の出身地。地震後ルフィ名義で8億円を寄付。"},{"k":"people","zh":"宮本武藏晚年在這裡的靈巖洞寫下《五輪書》","en":"Miyamoto Musashi wrote The Book of Five Rings in Reigando cave here late in life.","ja":"宮本武蔵は晩年、霊巌洞にこもって『五輪書』を著した。"},{"k":"work","zh":"漫畫《妖怪聯絡簿》大量描繪作者家鄉人吉的風景","en":"Natsume's Book of Friends draws heavily on the scenery of Hitoyoshi, the author's hometown.","ja":"『夏目友人帳』には作者の地元・人吉の風景が多く描かれる。"},{"k":"festival","zh":"山鹿燈籠祭中，女性頭頂金色燈籠，上千人一起跳舞","en":"At the Yamaga Lantern Festival, a thousand women dance with golden lanterns on their heads.","ja":"山鹿灯籠まつりでは女性が金灯籠を頭に載せ、千人で踊る。"},{"k":"origin","zh":"加藤清正嫌原地名第一個字含「畏」不吉，改成了猛獸的字","en":"Kato Kiyomasa disliked that the name's first character contained 'fear', so he swapped in an animal's character.","ja":"加藤清正は地名の一字目に「畏」が含まれるのを嫌い、獣の字に改めた。"},{"k":"record","zh":"西瓜產量全國第一","en":"It grows more watermelons than any other prefecture.","ja":"スイカの生産量が全国1位。"},{"k":"record","zh":"釋迦院參道石階共 3333 階，號稱日本第一","en":"The 3,333 stone steps up to Shakain temple are billed as Japan's longest stairway.","ja":"釈迦院の参道は3333段で、日本一の石段とされる。"},{"k":"symbol","zh":"縣魚是斑節蝦（車蝦）","en":"Its prefectural fish is the kuruma prawn.","ja":"県の魚はクルマエビ。"}],
"JP-44":[{"k":"symbol","zh":"縣花和縣樹都是「豐後梅」","en":"Both its prefectural flower and tree are the Bungo plum.","ja":"県の花と木はどちらも豊後梅。"},{"k":"people","zh":"《進擊的巨人》作者諫山創出身這裡的日田","en":"Attack on Titan creator Hajime Isayama is from Hita here.","ja":"『進撃の巨人』の諫山創は日田市出身。"},{"k":"people","zh":"AKB48 總選舉拿過 4 次第一的指原莉乃出身這裡","en":"Rino Sashihara, four-time winner of the AKB48 general election, is from here.","ja":"AKB48総選挙で4度1位の指原莉乃の出身地。"},{"k":"sport","zh":"日本輪椅籃球與輪椅馬拉松的發源地","en":"The birthplace of wheelchair basketball and wheelchair marathons in Japan.","ja":"日本の車いすバスケットボールと車いすマラソン発祥の地。"},{"k":"festival","zh":"ケベス祭中，戴怪面具的人衝進燃燒的蕨堆，把火星灑向人群","en":"At the Kebesu Festival, a masked figure charges into burning fern piles and scatters sparks on onlookers.","ja":"ケベス祭では奇妙な面のケベスが燃えるシダに突入し、火の粉を散らす。"},{"k":"origin","zh":"《風土記》說景行天皇讚嘆此地廣大，命名為「碩田國」","en":"In the Fudoki, Emperor Keiko marveled at how vast the land was and named it the 'land of great fields'.","ja":"『豊後国風土記』で景行天皇が広さに感嘆し「碩田国」と名付けた。"},{"k":"record","zh":"九重「夢」大吊橋離水面 173 公尺，是日本最高的步行專用橋","en":"The Kokonoe Yume suspension bridge, 173 m above the water, is Japan's highest pedestrian bridge.","ja":"九重“夢”大吊橋は水面から173m、歩行者専用橋で日本一高い。"},{"k":"record","zh":"再生能源自給率是全國都道府縣最高","en":"It has the highest renewable-energy self-sufficiency of any prefecture.","ja":"自然エネルギー自給率が全国の都道府県で最も高い。"}],
"JP-45":[{"k":"symbol","zh":"縣樹是加那利海棗（フェニックス）","en":"Its prefectural tree is the Canary Island date palm, known as 'phoenix'.","ja":"県の木はフェニックス。"},{"k":"people","zh":"前知事東國原英夫，原是北野武的大弟子「そのまんま東」","en":"Former governor Hideo Higashikokubaru was once comedian Sonomanma Higashi, Beat Takeshi's top disciple.","ja":"元知事の東国原英夫は、ビートたけしの一番弟子「そのまんま東」。"},{"k":"sport","zh":"老虎伍茲曾在這裡舉辦的鄧祿普鳳凰賽連續兩年奪冠","en":"Tiger Woods won back-to-back titles at the Dunlop Phoenix golf tournament held here.","ja":"タイガー・ウッズはここで開かれるダンロップフェニックスで連覇した。"},{"k":"festival","zh":"高千穗夜神樂在民家通宵演出 33 段，跳到隔天早上","en":"Takachiho's night kagura performs 33 dances all night in private homes, ending the next morning.","ja":"高千穂の夜神楽は民家で三十三番を夜通し舞い、翌朝まで続く。"},{"k":"record","zh":"小黃瓜產量全國第一","en":"It produces more cucumbers than any other prefecture.","ja":"キュウリの生産量が全国1位。"},{"k":"record","zh":"肉雞（白肉雞）產量全國第一","en":"It raises the most broiler chickens of any prefecture.","ja":"ブロイラーの生産が全国1位。"},{"k":"record","zh":"擁有日本最南端的天然滑雪場","en":"It has Japan's southernmost natural-snow ski area.","ja":"日本最南端の天然スキー場がある。"},{"k":"record","zh":"蘿蔔乾（切り干し大根）產量全國第一","en":"It produces more dried shredded daikon than any other prefecture.","ja":"切り干し大根の生産量が全国1位。"}],
"JP-46":[{"k":"symbol","zh":"縣鳥是琉璃色的松鴉「ルリカケス」","en":"Its prefectural bird is Lidth's jay, a lapis-blue jay.","ja":"県の鳥はルリカケス。"},{"k":"people","zh":"歌手長渕剛 2004 年在櫻島辦通宵演唱會，吸引約 7.5 萬人","en":"Singer Tsuyoshi Nagabuchi drew about 75,000 people to an all-night concert on Sakurajima in 2004.","ja":"長渕剛は2004年に桜島でオールナイトライブを開き、約7万5千人を集めた。"},{"k":"work","zh":"NHK 大河劇《篤姬》，主角出身島津家分家今和泉家","en":"NHK's taiga drama Atsuhime follows a heroine from the Imaizumi branch of the Shimazu clan.","ja":"大河ドラマ『篤姫』の主人公は島津家の分家・今和泉家の出身。"},{"k":"sport","zh":"劍術流派「示現流」講求第一刀定勝負，練習時對著木樁連砍","en":"The Jigen-ryu sword school stakes all on the first strike and trains by hacking at upright posts.","ja":"剣術・示現流は「二の太刀要らず」、立木打ちで稽古する。"},{"k":"festival","zh":"除夕夜來訪神「トシドン」挨家訓誡小孩，列入聯合國非遺","en":"On New Year's Eve, the visiting deity Toshidon scolds children door to door; it's UNESCO-listed.","ja":"大晦日に来訪神トシドンが家々で子どもを戒める。ユネスコ無形文化遺産。"},{"k":"origin","zh":"縣名據說來自霧島市的同名神宮","en":"The name is said to come from a shrine of the same name in Kirishima.","ja":"県名は霧島市にある同名の神宮に由来するとされる。"},{"k":"record","zh":"出水平原是日本最大的鶴群越冬地","en":"The Izumi plain is Japan's largest wintering ground for cranes.","ja":"出水は日本最大のツルの越冬地。"},{"k":"life","zh":"火山灰落得多時，公所會發「克灰袋」讓居民裝灰","en":"When volcanic ash piles up, local offices hand out special 'kokuhai' bags for residents to bag it.","ja":"降灰が多いと役所から克灰袋が配られ、灰を詰めて出す。"}],
"JP-47":[{"k":"symbol","zh":"縣鳥是野口啄木鳥（ノグチゲラ）","en":"Its prefectural bird is Pryer's woodpecker.","ja":"県の鳥はノグチゲラ。"},{"k":"people","zh":"歌后安室奈美惠出身這裡，從當地的演藝學校起步","en":"Pop star Namie Amuro comes from here and got her start at a local actors' school.","ja":"安室奈美恵の出身地。地元のアクターズスクールから羽ばたいた。"},{"k":"sport","zh":"拳王具志堅用高出身石垣島，衛冕 13 次是日本男子紀錄","en":"Boxer Yoko Gushiken, from Ishigaki, made 13 title defenses, a record for Japanese male champions.","ja":"石垣島出身の具志堅用高は13度防衛、日本男子世界王者の最多記録。"},{"k":"work","zh":"NHK 晨間劇《ちゅらさん》女主角在八重山的小濱島長大","en":"In NHK's morning drama Churasan, the heroine grows up on Kohama Island in the Yaeyama Islands.","ja":"朝ドラ『ちゅらさん』のヒロインは八重山の小浜島育ち。"},{"k":"festival","zh":"大綱挽的稻草繩曾獲金氏認證為世界最大，現在長 200 公尺、重 40 噸","en":"Its giant tug-of-war rope, once certified by Guinness as the world's largest, is now 200 m long and 40 tons.","ja":"大綱挽の綱はギネス認定の世界最大の綱で、今は全長200m・重さ40トン。"},{"k":"origin","zh":"奈良時代記載鑑真東渡的書中，把這裡寫作「阿兒奈波」","en":"An 8th-century account of the monk Jianzhen's voyage to Japan records it as 'Akonaha'.","ja":"奈良時代の『唐大和上東征伝』に「阿児奈波」として登場する。"},{"k":"record","zh":"全國唯一沒有一級河川的縣","en":"It's the only prefecture with no Class A (first-class) river.","ja":"全国で唯一、一級河川がない県。"},{"k":"life","zh":"因為長年缺水，許多住家屋頂上都裝著水塔","en":"Because of past water shortages, many homes have water tanks on their roofs.","ja":"水不足の歴史から、屋根に給水タンクを置く家が多い。"}]};
